  function seasonStickerChoices(){const sp=currentSpread();const list=[];CATEGORIES.forEach(c=>(sp.categories?.[c.id]||[]).forEach(st=>{if(st)list.push(st)}));return list;}
  function awardPickerModal(){const target=state.awardPickerTarget||state.addTarget||{};const award=AWARD_CATEGORIES.find(a=>a.id===target.aid);const current=currentAwards().featured[target.aid];const cards=seasonStickerChoices();const grid=cards.length?cards.map(st=>`<button class="award-picker-item${current&&current.id===st.id?' is-selected':''}" data-pick-award-card="${st.id}" title="${escapeHtml(st.name||'Karte')}"><div class="slot slot-teal">${stickerCardHTML(st,st.stickerNo||'',false)}</div></button>`).join(''):`<div class="award-picker-empty">Noch keine Karten in dieser Saison</div>`;return `<div class="modal-overlay"><div class="modal-box award-picker-modal"><div class="award-picker-actions"><div>${clubLogo(38)}<div class="award-picker-title">Karte auswählen</div><div class="award-picker-sub">${escapeHtml(award?.title||'Auszeichnung')} · ${seasonYearText(state.spread)}</div></div><button id="close-award-picker" class="award-picker-close"><i class="ti ti-x"></i></button></div><div class="award-picker-grid">${grid}</div><div style="margin-top:16px;display:flex;justify-content:flex-end"><button id="award-picker-new-card" class="award-picker-new"><i class="ti ti-plus"></i> Neue Karte erstellen</button></div></div></div>`}
  function trophyModal(edit){const t=edit?currentAwards().trophies[state.trophyTarget?.si]:{};return `<div class="modal-overlay"><div class="modal-box scrollable-modal" style="width:min(430px,96vw);padding:24px"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px"><div style="display:flex;align-items:center;gap:10px">${clubLogo(38)}<div><div style="font-size:16px;font-weight:bold;color:var(--blue)">${edit?'Titel bearbeiten':'Titel hinzufügen'}</div><div style="font-size:10px;color:#536070">Pokalbild mit Unterschrift</div></div></div><button id="close-trophy-modal" style="background:none;border:none;font-size:20px;cursor:pointer;color:#999"><i class="ti ti-x"></i></button></div><div style="text-align:center;margin-bottom:16px"><div id="trophy-photo-area" style="width:150px;height:200px;margin:0 auto 6px;border:2px dashed var(--blue);border-radius:8px;display:flex;align-items:center;justify-content:center;cursor:pointer;overflow:hidden;background:var(--photo-bg)">${t?.photo?`<img src="${t.photo}" style="width:100%;height:100%;object-fit:contain;object-position:center">`:`<div style="text-align:center;color:#fff"><i class="ti ti-trophy" style="font-size:42px"></i><div style="font-size:10px;margin-top:4px">Pokal-Foto</div></div>`}</div><input type="file" id="trophy-photo-input" accept="image/*" style="display:none"></div><div><label class="label-sm">Titel / Pokalname</label><input class="form-input" id="trophy-title" value="${escapeHtml(t?.title||'')}" placeholder="z. B. League Two Trophy"></div><button class="save-btn" id="save-trophy-btn">TITEL SPEICHERN</button>${edit?'<button class="delete-btn" id="delete-trophy-btn" style="width:100%;margin-top:10px">Titel löschen</button>':''}</div></div>`}
  function stripCloneIds(node){node.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));return node;}
  function cropCanvasToDataURL(canvas, srcX, srcY, srcW, srcH){
    const c=document.createElement('canvas');
    c.width=Math.max(1,Math.round(srcW));
    c.height=Math.max(1,Math.round(srcH));
    const ctx=c.getContext('2d');
    ctx.drawImage(canvas,srcX,srcY,srcW,srcH,0,0,c.width,c.height);
    const url=c.toDataURL('image/png');
    c.width=1;c.height=1;
    return url;
  }
  function stripCloneIds(node){
    if(node.nodeType===1){node.removeAttribute('id');node.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));}
    return node;
  }
  async function makePageFlipOverlay(dir){
    const album=document.querySelector('.album');
    if(!album || window.matchMedia('(max-width:980px)').matches)return 0;
    const rect=album.getBoundingClientRect();
    const leftPage=album.querySelector('.page-left');
    const rightPage=album.querySelector('.page-right');
    if(!leftPage || !rightPage)return 0;
    const lRect=leftPage.getBoundingClientRect();
    const rRect=rightPage.getBoundingClientRect();
    const movingSource=dir>0?rightPage:leftPage;
    const mRect=dir>0?rRect:lRect;
    const duration=380;
    const overlay=document.createElement('div');
    overlay.className='page-flip-overlay '+(dir>0?'page-flip-next':'page-flip-prev');
    overlay.style.left=rect.left+'px';
    overlay.style.top=rect.top+'px';
    overlay.style.width=rect.width+'px';
    overlay.style.height=rect.height+'px';
    const bg=document.createElement('div');
    bg.className='page-flip-shadow';
    overlay.appendChild(bg);
    function addStatic(page,r){
      const box=document.createElement('div');
      box.className='page-flip-static';
      box.style.left=(r.left-rect.left)+'px';
      box.style.width=r.width+'px';
      box.style.height=r.height+'px';
      box.appendChild(stripCloneIds(page.cloneNode(true)));
      overlay.appendChild(box);
    }
    addStatic(leftPage,lRect);
    addStatic(rightPage,rRect);
    const sheet=document.createElement('div');
    sheet.className='page-flip-sheet';
    sheet.style.left=(mRect.left-rect.left)+'px';
    sheet.style.width=mRect.width+'px';
    sheet.style.height=mRect.height+'px';
    const front=document.createElement('div');
    front.className='page-flip-face front';
    front.appendChild(stripCloneIds(movingSource.cloneNode(true)));
    const back=document.createElement('div');
    back.className='page-flip-face back';
    sheet.appendChild(front);
    sheet.appendChild(back);
    overlay.appendChild(sheet);
    document.body.appendChild(overlay);
    album.style.visibility='hidden';
    await new Promise(requestAnimationFrame);
    setTimeout(()=>{try{overlay.remove();album.style.visibility='';}catch(e){}},duration+30);
    return duration;
  }
  async function turnPage(dir){ensureSeasonPages();if(state.isTurningPage)return;const maxSeason=state.spreads.length-1;let ns=state.spread,np=state.seasonPage||0;if(dir>0){if(np===0)np=1;else if(ns<maxSeason){ns++;np=0;}else return;}else{if(np===1)np=0;else if(ns>0){ns--;np=1;}else return;}state.isTurningPage=true;const delay=await makePageFlipOverlay(dir)||0;setTimeout(()=>{state.spread=ns;state.seasonPage=np;state.isTurningPage=false;setState({});saveState();},delay||0);}
  const oldAttach=attachListeners;
  attachListeners=function(){oldAttach();ensureSeasonPages();const pp=document.getElementById('nav-prev');if(pp)pp.onclick=()=>turnPage(-1);const pn=document.getElementById('nav-next');if(pn)pn.onclick=()=>turnPage(1);if(pp){const disabled=state.spread===0&&(state.seasonPage||0)===0;pp.disabled=disabled;pp.style.background=disabled?'rgba(255,255,255,.1)':'rgba(215,169,59,.9)';pp.style.color=disabled?'#444':'#071932'}if(pn){const disabled=state.spread>=totalSpreads()-1&&(state.seasonPage||0)===1;pn.disabled=disabled;pn.style.background=disabled?'rgba(255,255,255,.1)':'rgba(215,169,59,.9)';pn.style.color=disabled?'#444':'#071932'}const as=document.getElementById('add-spread-btn');if(as)as.onclick=()=>{ensureSeasonPages();const prev=state.leagueSeasons?.[state.spreads.length-1]||{leagueIndex:3,years:{},places:{}};const ns=[...state.spreads,cloneSpreadFromPrevious(state.nextId++)];state.leagueSeasons=state.leagueSeasons||[];state.leagueSeasons.push({leagueIndex:prev.leagueIndex,years:{...(prev.years||{})},places:{...(prev.places||{})}});state.awards.push(blankAwards());setState({spreads:ns,spread:ns.length-1,seasonPage:0});saveState();};const gab=document.getElementById('global-add-btn');if(gab&&(state.seasonPage||0)===1)gab.onclick=()=>{const first=AWARD_CATEGORIES.find(a=>!currentAwards().featured[a.id]);if(first)setState({showAwardPicker:true,awardPickerTarget:{award:true,aid:first.id,si:0},addTarget:{award:true,aid:first.id,si:0}});else{const aw=currentAwards();let si=aw.trophies.findIndex(x=>!x);if(si<0){aw.trophies.push(null);si=aw.trophies.length-1;}setState({showTrophyAdd:true,trophyTarget:{trophy:true,si}})}};document.querySelectorAll('[data-award][data-empty], [data-award] .slot-empty').forEach(el=>{el.onclick=e=>{const host=e.currentTarget.closest('[data-award]')||e.currentTarget;setState({showAwardPicker:true,awardPickerTarget:{award:true,aid:host.dataset.award,si:0},addTarget:{award:true,aid:host.dataset.award,si:0}})}});const cap=document.getElementById('close-award-picker');if(cap)cap.onclick=()=>setState({showAwardPicker:false,awardPickerTarget:null,addTarget:null});document.querySelectorAll('[data-pick-award-card]').forEach(btn=>{btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const id=+btn.dataset.pickAwardCard;const src=seasonStickerChoices().find(st=>st.id===id);const target=state.awardPickerTarget||state.addTarget;if(src&&target){currentAwards().featured[target.aid]={...src};const key=targetKey(target);setState({showAwardPicker:false,awardPickerTarget:null,addTarget:null,newKey:key});saveState();setTimeout(()=>setState({newKey:null}),900);}},true);});const apn=document.getElementById('award-picker-new-card');if(apn)apn.onclick=()=>{const target=state.awardPickerTarget||state.addTarget;setState({showAwardPicker:false,showAdd:true,addTarget:target});};document.querySelectorAll('[data-trophy-empty]').forEach(el=>{el.onclick=()=>setState({showTrophyAdd:true,trophyTarget:{trophy:true,si:+el.dataset.si}})});const ats=document.getElementById('add-trophy-slot');if(ats)ats.onclick=()=>{currentAwards().trophies.push(null);setState({});saveState();};document.querySelectorAll('[data-edit-trophy]').forEach(btn=>{btn.onclick=e=>{e.stopPropagation();setState({showTrophyEdit:true,trophyTarget:{trophy:true,si:+btn.dataset.editTrophy}})}});document.querySelectorAll('[data-trophy="1"] .award-card').forEach(card=>{card.onclick=e=>{if(e.target.closest('[data-edit-trophy]'))return;setState({showTrophyEdit:true,trophyTarget:{trophy:true,si:+card.closest('[data-trophy]').dataset.si}})}});const saveStickerBtn=document.getElementById('save-sticker-btn');
    if(saveStickerBtn && (((state.addTarget||{}).award)||((state.editTarget||{}).award))){
      saveStickerBtn.onclick=()=>{const name=(document.getElementById('f-name')||{}).value?.trim();if(!name)return;const pos=normalizePos((document.getElementById('f-pos')||{}).value||'TW');const oldSticker=state.showEdit?state.editTarget.sticker:{};const status=(document.getElementById('f-status')||{}).value||'active';const sticker={...oldSticker,id:state.showEdit?state.editTarget.sticker.id:state.nextId++,stickerNo:state.showEdit?(state.editTarget.sticker.stickerNo||state.nextStickerNo++):state.nextStickerNo++,name,nickname:(document.getElementById('f-nickname')||{}).value?.trim()||'',jerseyNumber:((document.getElementById('f-jersey')||{}).value||'').replace(/\D/g,'').slice(0,3),photo:currentPhoto||(state.showEdit?state.editTarget.sticker.photo:null),position:pos,nationality:(document.getElementById('f-nat')||{}).value||'England',height:(document.getElementById('f-height')||{}).value?.trim()||'',birthdate:(document.getElementById('f-birth')||{}).value||'',yiYear:((document.getElementById('f-yi-year')||{}).value||'').replace(/\D/g,'').slice(0,4),proDebut:(document.getElementById('f-debut')||{}).value?.trim()||'',trainedAt:(document.getElementById('f-trained')||{}).value?.trim()||'',status,sold:status==='sold',loaned:status==='loan',transferFee:(document.getElementById('f-fee')||{}).value?.trim()||'',leftDate:(document.getElementById('f-left-date')||{}).value||'',buyingClub:(document.getElementById('f-buying-club')||{}).value?.trim()||'',contractExpired:!!(document.getElementById('f-contract-expired')||{}).checked,gamesForClub:(document.getElementById('f-games')||{}).value?.trim()||'',patron:(document.getElementById('f-patron')||{}).value?.trim()||'',sponsorshipSince:(document.getElementById('f-sponsorship-since')||{}).value?.trim()||'',note:(document.getElementById('f-note')||{}).value?.trim()||''};const target=state.showAdd?state.addTarget:state.editTarget;currentAwards().featured[target.aid]=sticker;const key=targetKey(target);setState({showAdd:false,showEdit:false,addTarget:null,editTarget:null,newKey:key});saveState();setTimeout(()=>setState({newKey:null}),900);};
    }
    const delStickerBtn=document.getElementById('confirm-del-sticker');
    if(delStickerBtn && state.profileTarget && state.profileTarget.award){
      delStickerBtn.onclick=()=>{currentAwards().featured[state.profileTarget.aid]=null;setState({confirmDelSticker:false,showProfile:false,profileTarget:null});saveState();};
    }
    const ctm=document.getElementById('close-trophy-modal');if(ctm)ctm.onclick=()=>setState({showTrophyAdd:false,showTrophyEdit:false,trophyTarget:null});let trophyPhoto=state.trophyTarget?currentAwards().trophies[state.trophyTarget.si]?.photo||null:null;const tpa=document.getElementById('trophy-photo-area');if(tpa)tpa.onclick=()=>document.getElementById('trophy-photo-input')?.click();const tpi=document.getElementById('trophy-photo-input');if(tpi)tpi.onchange=e=>{const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=ev=>{trophyPhoto=ev.target.result;if(tpa)tpa.innerHTML=`<img src="${trophyPhoto}" style="width:100%;height:100%;object-fit:contain;object-position:center">`;};r.readAsDataURL(file)};const st=document.getElementById('save-trophy-btn');if(st)st.onclick=()=>{const si=state.trophyTarget?.si??0;currentAwards().trophies[si]={id:Date.now(),title:(document.getElementById('trophy-title')||{}).value?.trim()||'Titel',photo:trophyPhoto};const key=`${state.spread}-trophy-${si}`;setState({showTrophyAdd:false,showTrophyEdit:false,trophyTarget:null,newKey:key});saveState();setTimeout(()=>setState({newKey:null}),900)};const dt=document.getElementById('delete-trophy-btn');if(dt)dt.onclick=()=>{const si=state.trophyTarget?.si;if(si!==undefined)currentAwards().trophies[si]=null;setState({showTrophyEdit:false,trophyTarget:null});saveState();};const cds=document.getElementById('confirm-del-spread');if(cds)cds.onclick=()=>{if(state.spreads.length<=1)return setState({confirmDelSpread:false});const idx=state.spread;state.spreads=state.spreads.filter((_,i)=>i!==idx);if(Array.isArray(state.leagueSeasons))state.leagueSeasons=state.leagueSeasons.filter((_,i)=>i!==idx);if(Array.isArray(state.awards))state.awards=state.awards.filter((_,i)=>i!==idx);setState({spread:Math.max(0,Math.min(idx,state.spreads.length-1)),seasonPage:0,confirmDelSpread:false});saveState();};};
