// --- Nachbesserung: Titel/Pokale verhalten sich wie eine Rubrik mit mehreren Plaetzen ---
(function(){
  function awardsForCurrent(){
    if(!Array.isArray(state.awards)) state.awards=[];
    if(!state.awards[state.spread]) state.awards[state.spread]={featured:{},trophies:[null]};
    const aw=state.awards[state.spread];
    if(!Array.isArray(aw.trophies)) aw.trophies=[null];
    return aw;
  }
  function tidyTrophyPlaceholders(){
    if(!Array.isArray(state.awards)) return;
    state.awards.forEach(aw=>{
      if(!aw) return;
      if(!Array.isArray(aw.trophies)) aw.trophies=[];
      const filled=aw.trophies.filter(Boolean);
      filled.push(null);
      aw.trophies=filled;
    });
  }
  const previousLoadState=loadState;
  loadState=async function(){
    await previousLoadState();
    tidyTrophyPlaceholders();
    render();
  };
  const previousSaveState=saveState;
  saveState=async function(){
    tidyTrophyPlaceholders();
    await previousSaveState();
  };
  const previousAttachListeners=attachListeners;
  attachListeners=function(){
    previousAttachListeners();
    const addBtn=document.getElementById('add-trophy-slot');
    if(addBtn){
      addBtn.onclick=()=>{const aw=awardsForCurrent();aw.trophies.push(null);setState({});saveState();};
    }
    const saveBtn=document.getElementById('save-trophy-btn');
    if(saveBtn){
      saveBtn.onclick=()=>{
        const aw=awardsForCurrent();
        const si=state.trophyTarget?.si??0;
        const img=document.querySelector('#trophy-photo-area img');
        const trophyPhoto=img?img.getAttribute('src'):(aw.trophies[si]?.photo||null);
        aw.trophies[si]={id:Date.now(),title:(document.getElementById('trophy-title')||{}).value?.trim()||'Titel',photo:trophyPhoto};
        if(!aw.trophies.some(x=>!x)) aw.trophies.push(null);
        const key=`${state.spread}-trophy-${si}`;
        setState({showTrophyAdd:false,showTrophyEdit:false,trophyTarget:null,newKey:key});
        saveState();
        setTimeout(()=>setState({newKey:null}),900);
      };
    }
    const delBtn=document.getElementById('delete-trophy-btn');
    if(delBtn){
      delBtn.onclick=()=>{const aw=awardsForCurrent();const si=state.trophyTarget?.si;if(si!==undefined)aw.trophies[si]=null;tidyTrophyPlaceholders();setState({showTrophyEdit:false,trophyTarget:null});saveState();};
    }
  };
})();


// --- Nachbesserung: Auszeichnungen per rotem X leeren und danach neu auswaehlen ---
(function(){
  const prevAttachListeners=attachListeners;
  attachListeners=function(){
    prevAttachListeners();
    document.querySelectorAll('[data-clear-award]').forEach(btn=>{
      btn.onclick=(e)=>{
        e.preventDefault();
        e.stopPropagation();
        const aid=btn.dataset.clearAward;
        if(!aid)return;
        if(!Array.isArray(state.awards)) state.awards=[];
        if(!state.awards[state.spread]) state.awards[state.spread]={featured:{},trophies:[null]};
        if(!state.awards[state.spread].featured) state.awards[state.spread].featured={};
        state.awards[state.spread].featured[aid]=null;
        setState({
          showAwardPicker:true,
          awardPickerTarget:{award:true,aid,si:0},
          addTarget:{award:true,aid,si:0},
          showProfile:false,
          profileTarget:null
        });
        saveState();
      };
    });
  };
})();


// --- Finale User-Anpassungen: einfache Animation, Entfernen-Buttons, Liga-Historie ---
(function(){
  const finalStyle=document.createElement('style');
  finalStyle.textContent=`
    /* Einfache, robuste Umblätter-Animation */
    .album.simple-page-exit-next{animation:simpleAlbumExitNext .16s ease-in forwards!important;will-change:transform,opacity!important}
    .album.simple-page-exit-prev{animation:simpleAlbumExitPrev .16s ease-in forwards!important;will-change:transform,opacity!important}
    .album.simple-page-enter-next{animation:simpleAlbumEnterNext .18s ease-out forwards!important;will-change:transform,opacity!important}
    .album.simple-page-enter-prev{animation:simpleAlbumEnterPrev .18s ease-out forwards!important;will-change:transform,opacity!important}
    @keyframes simpleAlbumExitNext{from{opacity:1;transform:translateX(0) scale(1)}to{opacity:.12;transform:translateX(-18px) scale(.992)}}
    @keyframes simpleAlbumExitPrev{from{opacity:1;transform:translateX(0) scale(1)}to{opacity:.12;transform:translateX(18px) scale(.992)}}
    @keyframes simpleAlbumEnterNext{from{opacity:.12;transform:translateX(18px) scale(.992)}to{opacity:1;transform:translateX(0) scale(1)}}
    @keyframes simpleAlbumEnterPrev{from{opacity:.12;transform:translateX(-18px) scale(.992)}to{opacity:1;transform:translateX(0) scale(1)}}

    /* Alte komplexe Flip-Ebenen komplett aus dem Weg nehmen */
    .page-flip-overlay{display:none!important}

    /* Entfernen-Buttons auf eingeklebten Karten */
    .sticker-remove-x{position:absolute!important;top:-8px!important;right:-8px!important;width:23px!important;height:23px!important;border-radius:50%!important;border:2px solid #fff!important;background:var(--red)!important;color:#fff!important;display:flex!important;align-items:center!important;justify-content:center!important;cursor:pointer!important;box-shadow:0 4px 10px rgba(0,0,0,.34)!important;z-index:50!important;font-size:13px!important;line-height:1!important}
    .sticker-remove-x:hover{transform:scale(1.08)!important}
    .slot-teal,.parking-slot,.award-selected,[data-trophy="1"]{position:relative!important}

    /* Alter / Seit / Seriennummer nochmals groesser */
    .st-bottom-bar{font-size:clamp(6.85px,.62vw,9.05px)!important;font-weight:400!important;font-family:monospace!important}
    .st-bottom-bar .bar-value{font-size:clamp(8.35px,.75vw,11px)!important;font-weight:400!important;font-family:monospace!important}
    .sticker-no-badge{font-size:clamp(8.35px,.77vw,11.55px)!important}

    /* Liga-Historie */
    .league-panel.history-panel{width:min(390px,30vw)!important;max-height:72vh!important;overflow:auto!important;padding-right:3px!important}
    .league-row.history-row{display:grid!important;grid-template-columns:1fr auto!important;align-items:center!important;row-gap:6px!important;min-height:48px!important;padding:11px 12px!important;font-size:13px!important}
    .league-name{font-size:13px!important;line-height:1.1!important}
    .league-history{grid-column:1 / -1!important;display:flex!important;flex-wrap:wrap!important;gap:5px!important;margin-top:1px!important}
    .league-history-chip{font-family:monospace!important;font-size:10.5px!important;line-height:1!important;border:1px solid currentColor!important;border-radius:999px!important;padding:4px 6px!important;background:rgba(255,255,255,.12)!important;color:inherit!important;opacity:.88!important;white-space:nowrap!important}
    .league-row.active .league-history-chip{background:rgba(21,59,115,.12)!important;color:var(--blue)!important;opacity:1!important}
    .league-place{width:86px!important;min-height:31px!important;font-size:12px!important}
    .league-year{width:74px!important;min-height:28px!important;font-size:12px!important}
  `;
  document.head.appendChild(finalStyle);

  function ensureLeagueData(){
    if(!Array.isArray(state.leagueSeasons)) state.leagueSeasons=[];
    for(let i=0;i<state.spreads.length;i++){
      if(!state.leagueSeasons[i]) state.leagueSeasons[i]={leagueIndex:i===0?3:(state.leagueSeasons[i-1]?.leagueIndex??3),years:{},places:{}};
      if(!state.leagueSeasons[i].years) state.leagueSeasons[i].years={};
      if(!state.leagueSeasons[i].places) state.leagueSeasons[i].places={};
      if(i===0) state.leagueSeasons[i].leagueIndex=3;
    }
  }
  function yearCodeForSeason(i){
    const txt=seasonYearText(i);
    const m=txt.match(/\/(\d{2})$/);
    return m?m[1]:String(2026+i).slice(-2);
  }
  function historyForLeague(leagueIndex){
    ensureLeagueData();
    const rows=[];
    for(let si=0;si<=state.spread && si<state.leagueSeasons.length;si++){
      const val=(state.leagueSeasons[si].places||{})[leagueIndex];
      if(val!==undefined && String(val).trim()) rows.push({year:yearCodeForSeason(si),place:String(val).trim()});
    }
    return rows;
  }
  function renderLeagueHistoryPanel(){
    ensureLeagueData();
    const LEAGUES=['Premier League','Football League Championship','Football League One','Football League Two'];
    const data=state.leagueSeasons[state.spread]||{leagueIndex:3,years:{},places:{}};
    const locked=state.spread===0;
    let html='<div class="league-panel history-panel">';
    LEAGUES.forEach((l,i)=>{
      const chips=historyForLeague(i).map(h=>`<span class="league-history-chip">${escapeHtml(h.year)} · ${escapeHtml(h.place)}</span>`).join('');
      html+=`<div class="league-row history-row ${data.leagueIndex===i?'active':''} ${locked?'locked':''}" data-league-index="${i}" title="${locked?'Saison 1 startet fest in League Two':'Liga für diese Saison setzen'}"><span class="league-name">${l}</span><input class="league-place" data-league-place="${i}" maxlength="6" placeholder="Platz" value="${escapeHtml(data.places?.[i]||'')}">${chips?`<div class="league-history">${chips}</div>`:''}</div>`;
      if(i<LEAGUES.length-1){const key=`${i}-${i+1}`;html+=`<div class="league-gap"><input class="league-year" data-league-year="${key}" maxlength="4" inputmode="numeric" placeholder="Jahr" value="${escapeHtml(data.years?.[key]||'')}"></div>`;}
    });
    html+='</div>';
    return html;
  }
  function bindLeagueHistoryPanel(){
    document.querySelector('.league-panel')?.remove();
    const shell=document.querySelector('.app-shell');
    if(!shell) return;
    shell.insertAdjacentHTML('beforeend',renderLeagueHistoryPanel());
    document.querySelectorAll('[data-league-index]').forEach(el=>{
      el.onclick=(ev)=>{if(ev.target.closest('input'))return;if(state.spread===0)return;ensureLeagueData();state.leagueSeasons[state.spread].leagueIndex=+el.dataset.leagueIndex;setState({});saveState();};
    });
    document.querySelectorAll('[data-league-year]').forEach(inp=>{
      inp.oninput=()=>{inp.value=inp.value.replace(/\D/g,'').slice(0,4)};
      inp.onchange=()=>{ensureLeagueData();state.leagueSeasons[state.spread].years[inp.dataset.leagueYear]=inp.value;saveState();};
    });
    document.querySelectorAll('[data-league-place]').forEach(inp=>{
      inp.oninput=()=>{inp.value=inp.value.replace(/[^0-9.]/g,'').slice(0,6)};
      inp.onchange=()=>{ensureLeagueData();state.leagueSeasons[state.spread].places[inp.dataset.leaguePlace]=inp.value;setState({});saveState();};
    });
  }
  function pageDestination(dir){
    const maxSeason=state.spreads.length-1;
    let ns=state.spread,np=state.seasonPage||0;
    if(dir>0){if(np===0)np=1;else if(ns<maxSeason){ns++;np=0;}else return null;}
    else{if(np===1)np=0;else if(ns>0){ns--;np=1;}else return null;}
    return {ns,np};
  }
  function simpleTurnPage(dir){
    if(state.isTurningPage) return;
    const dest=pageDestination(dir);
    if(!dest) return;
    const album=document.querySelector('.album');
    const exitClass=dir>0?'simple-page-exit-next':'simple-page-exit-prev';
    const enterClass=dir>0?'simple-page-enter-next':'simple-page-enter-prev';
    state.isTurningPage=true;
    if(album) album.classList.add(exitClass);
    setTimeout(()=>{
      state.spread=dest.ns;
      state.seasonPage=dest.np;
      state.isTurningPage=false;
      setState({});
      saveState();
      requestAnimationFrame(()=>{
        const newAlbum=document.querySelector('.album');
        if(newAlbum){
          newAlbum.classList.add(enterClass);
          setTimeout(()=>newAlbum.classList.remove(enterClass),210);
        }
      });
    },165);
  }
  function removeStickerFromContext(btn){
    const trophy=btn.closest('[data-trophy="1"]');
    if(trophy){
      const si=+trophy.dataset.si;
      if(Array.isArray(state.awards)&&state.awards[state.spread]&&Array.isArray(state.awards[state.spread].trophies)){
        state.awards[state.spread].trophies[si]=null;
        setState({showProfile:false,profileTarget:null});
        saveState();
      }
      return;
    }
    const awardHost=btn.closest('[data-award-cat]')||btn.closest('[data-award]');
    if(awardHost){
      const aid=awardHost.dataset.awardCat||awardHost.dataset.award;
      if(aid && Array.isArray(state.awards) && state.awards[state.spread]){
        state.awards[state.spread].featured=state.awards[state.spread].featured||{};
        state.awards[state.spread].featured[aid]=null;
        setState({showProfile:false,profileTarget:null});
        saveState();
      }
      return;
    }
    const card=btn.closest('.sticker-card');
    const id=card?+card.dataset.id:0;
    const loc=id?findSticker(id):null;
    if(loc){
      const arr=getSlotArray(loc);
      if(arr) arr[loc.si]=null;
      tidyCategoryPlaceholders();
      setState({showProfile:false,profileTarget:null});
      saveState();
    }
  }
  function addRemoveButtons(){
    document.querySelectorAll('.sticker-card[data-id]').forEach(card=>{
      if(card.querySelector('.sticker-remove-x')) return;
      const btn=document.createElement('button');
      btn.className='sticker-remove-x';
      btn.type='button';
      btn.title='Sticker entfernen';
      btn.innerHTML='<i class="ti ti-x"></i>';
      btn.onclick=(e)=>{e.preventDefault();e.stopPropagation();removeStickerFromContext(btn);};
      card.appendChild(btn);
    });
    document.querySelectorAll('[data-trophy="1"] .award-card').forEach(card=>{
      if(card.querySelector('.sticker-remove-x')) return;
      const btn=document.createElement('button');
      btn.className='sticker-remove-x';
      btn.type='button';
      btn.title='Titel entfernen';
      btn.innerHTML='<i class="ti ti-x"></i>';
      btn.onclick=(e)=>{e.preventDefault();e.stopPropagation();removeStickerFromContext(btn);};
      card.appendChild(btn);
    });
  }
  const prevSaveState=saveState;
  saveState=async function(){
    ensureLeagueData();
    await prevSaveState();
  };
  const prevAttach=attachListeners;
  attachListeners=function(){
    prevAttach();
    bindLeagueHistoryPanel();
    addRemoveButtons();
    const pp=document.getElementById('nav-prev');
    const pn=document.getElementById('nav-next');
    if(pp){pp.onclick=()=>simpleTurnPage(-1);const disabled=state.spread===0&&(state.seasonPage||0)===0;pp.disabled=disabled;}
    if(pn){pn.onclick=()=>simpleTurnPage(1);const disabled=state.spread>=totalSpreads()-1&&(state.seasonPage||0)===1;pn.disabled=disabled;}
    const as=document.getElementById('add-spread-btn');
    if(as){
      as.onclick=()=>{
        ensureLeagueData();
        const prev=state.leagueSeasons?.[state.spreads.length-1]||{leagueIndex:3,years:{},places:{}};
        const ns=[...state.spreads,cloneSpreadFromPrevious(state.nextId++)];
        state.leagueSeasons=state.leagueSeasons||[];
        state.leagueSeasons.push({leagueIndex:prev.leagueIndex,years:{...(prev.years||{})},places:{}});
        if(Array.isArray(state.awards)) state.awards.push(typeof blankAwards==='function'?blankAwards():{featured:{},trophies:[null]});
        setState({spreads:ns,spread:ns.length-1,seasonPage:0});
        saveState();
      };
    }
  };
})();


