    const hasVal=v=>v!==undefined&&v!==null&&String(v).trim()!=='';
    const pickLoose=(...keys)=>{const wanted=keys.map(normKey);for(const [k,v] of Object.entries(row||{})){if(wanted.includes(normKey(k))&&hasVal(v))return v;}return '';};
    const num=(...keys)=>{const v=String(pickLoose(...keys)).replace(',', '.').replace(/[^0-9.\-]/g,'');return v===''?'':v;};
    const asText=v=>hasVal(v)?String(v).trim():'';
