    const starValue=v=>{const raw=asText(v);if(!raw)return '';if(raw.indexOf('★')>=0||raw.indexOf('☆')>=0)return raw;const n=parseFloat(raw.replace(',', '.').replace(/[^0-9.\-]/g,''));if(!isFinite(n))return raw;const full=Math.max(0,Math.min(5,Math.round(n)));return '★'.repeat(full)+'☆'.repeat(5-full);};
    const parseImportAge=v=>{const raw=asText(v);const m=raw.match(/\d+/);return m?String(parseInt(m[0],10)):'';};
    const intAttr=v=>{const m=String(v??'').replace(',', '.').match(/-?\d+(?:\.\d+)?/);return m?Math.round(parseFloat(m[0])):'';};
    const cleanTrait=v=>{/keine\s+eigenschaften/i.test(String(v||''))?null:null;return /keine\s+eigenschaften/i.test(String(v||''))?'':asText(v);};
    const pickOrdered=(...keys)=>{for(const key of keys){const v=pickLoose(key);if(hasVal(v))return v;}return '';};
    const parseDateValue=v=>{
      const raw=asText(v); if(!raw)return '';
      if(/^\d{4}-\d{2}-\d{2}$/.test(raw))return raw;
      let m=raw.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{2,4})$/);
      if(m){let y=m[3]; if(y.length===2)y=(parseInt(y,10)>50?'19':'20')+y; return `${y.padStart(4,'0')}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;}
      m=raw.match(/^(\d{4})[.\/-](\d{1,2})[.\/-](\d{1,2})$/);
      if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
      return raw;
    };
