// --- Patch: Read-only Online-Export als eigenstaendige HTML-Datei ---
(function(){
  const style=document.createElement('style');
  style.textContent=`
    .readonly-export-btn{height:42px!important;border:2px solid rgba(215,169,59,.75)!important;background:rgba(200,16,46,.86)!important;color:#fff!important;border-radius:999px!important;padding:0 15px!important;font-size:12px!important;font-weight:900!important;letter-spacing:.8px!important;text-transform:uppercase!important;cursor:pointer!important;display:inline-flex!important;align-items:center!important;gap:7px!important;box-shadow:0 6px 18px rgba(0,0,0,.22)!important;white-space:nowrap!important}
    .readonly-export-btn:hover{background:rgba(200,16,46,1)!important;transform:translateY(-1px)!important}
    body.public-view .global-add,body.public-view #add-spread-btn,body.public-view #sticker-import-btn,body.public-view #readonly-export-btn,body.public-view #delete-spread-btn,body.public-view #season-lock-toggle,body.public-view .season-lock-btn,body.public-view .slot-del,body.public-view .sticker-remove-x,body.public-view .card-remove-overlay,body.public-view .edit-icon,body.public-view .award-remove-btn,body.public-view .trophy-add-card,body.public-view .fm-profile-actions,body.public-view .delete-btn,body.public-view .edit-action-btn,body.public-view .parking-add,body.public-view [data-add-slot],body.public-view [data-history-edit],body.public-view [data-history-delete-final],body.public-view [data-history-delete],body.public-view .manual-history-delete,body.public-view .manual-history-add,body.public-view .manual-history-form{display:none!important}
    body.public-view .slot-empty,body.public-view .parking-empty{pointer-events:none!important;cursor:default!important}
    body.public-view .sticker-card,body.public-view .award-card,body.public-view .coach-sticker-mini{cursor:pointer!important}
    body.public-view input,body.public-view textarea,body.public-view select{pointer-events:none!important;user-select:none!important}
    body.public-view .league-row{cursor:default!important}
    body.public-view .nav-label:after{content:'Online-Ansicht';display:block;margin-top:4px;color:rgba(215,169,59,.9);font-size:10px;font-weight:900;letter-spacing:1px;text-transform:uppercase}
  `;
  document.head.appendChild(style);

  function safeJson(value){
    return JSON.stringify(value).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
  }
  const ASSET_INLINE_CACHE={};
  function looksLikeImageUrl(v){
    if(typeof v!=='string')return false;
    if(v.startsWith('data:image/'))return false;
    if(v.startsWith('blob:'))return true;
    if(!/^https?:\/\//i.test(v))return false;
    return /\.(png|jpe?g|gif|webp|svg)([?#].*)?$/i.test(v) || /upload\.wikimedia\.org/i.test(v);
  }
  async function urlToDataUrl(url){
    if(!looksLikeImageUrl(url))return url;
    if(ASSET_INLINE_CACHE[url])return ASSET_INLINE_CACHE[url];
    try{
      const res=await fetch(url,{mode:'cors',cache:'force-cache'});
      if(!res.ok)throw new Error('HTTP '+res.status);
      const blob=await res.blob();
      const data=await new Promise((resolve,reject)=>{
        const reader=new FileReader();
        reader.onload=()=>resolve(reader.result);
        reader.onerror=reject;
        reader.readAsDataURL(blob);
      });
      ASSET_INLINE_CACHE[url]=data;
      return data;
    }catch(e){
      console.warn('Grafik konnte nicht in den Online-Export eingebettet werden:',url,e);
      ASSET_INLINE_CACHE[url]=url;
      return url;
    }
  }
  async function inlineGraphicsInValue(value,seen){
    if(value==null)return value;
    if(typeof value==='string')return looksLikeImageUrl(value)?await urlToDataUrl(value):value;
    if(typeof value!=='object')return value;
    seen=seen||new WeakSet();
    if(seen.has(value))return value;
    seen.add(value);
    if(Array.isArray(value)){
      const out=[];
      for(const item of value)out.push(await inlineGraphicsInValue(item,seen));
      return out;
    }
    const out={};
    for(const k of Object.keys(value))out[k]=await inlineGraphicsInValue(value[k],seen);
    return out;
  }
  async function inlineGraphicsInSource(source){
    const urls=new Set();
    const add=u=>{if(looksLikeImageUrl(u))urls.add(u)};
    source.replace(/(?:src|href)=["']([^"']+)["']/gi,(_,u)=>{add(u);return _});
    source.replace(/url\((['"]?)([^)'"]+)\1\)/gi,(_,q,u)=>{add(u);return _});
    source.replace(/https?:\/\/[^"'\s)]+/gi,u=>{add(u);return u});
    for(const url of urls){
      const data=await urlToDataUrl(url);
      if(data!==url)source=source.split(url).join(data);
    }
    return source;
  }
  async function storageSnapshot(){
    const base=await inlineGraphicsInValue({spreads:state.spreads||[],parking:state.parking||[],nextId:state.nextId||10,nextStickerNo:state.nextStickerNo||1});
    const extra=await inlineGraphicsInValue({coach:state.coach||null,leagueSeasons:state.leagueSeasons||[]});
    const seasonPages=await inlineGraphicsInValue({awards:state.awards||[],seasonPage:state.seasonPage||0});
    const archive=await inlineGraphicsInValue(state.stickerArchive||[]);
    const leagueHistory=await inlineGraphicsInValue(state.leagueHistoryEntries||[]);
    const autoHistory=await inlineGraphicsInValue(state.autoLeagueHistory||[]);
    const locks=state.seasonLocked||[];
    const historyPayload={leagueHistoryEntries:leagueHistory,marker:'readonly-export'};
    const map={
      'crewe-categorized-v1':JSON.stringify(base),
      'crewe-extra-v2':JSON.stringify(extra),
      'crewe-season-pages-v1':JSON.stringify(seasonPages),
      'crewe-sticker-archive-v2':JSON.stringify(archive),
      'crewe-final-profile-history-v1':JSON.stringify(historyPayload),
      'crewe-league-history-v1':JSON.stringify(leagueHistory),
      'crewe-league-history-vorsaison-v3':JSON.stringify(historyPayload),
      'crewe-auto-league-history-v1':JSON.stringify(autoHistory),
      'crewe-auto-league-history-reset-v1':'1',
      'crewe-season-locks-v1':JSON.stringify(locks)
    };
    return map;
  }
  function fileNameForExport(){
    const d=new Date();
    const pad=n=>String(n).padStart(2,'0');
    return `crewe-alexandra-online-${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}.html`;
  }
  async function buildReadOnlyHtml(){
    let source='<!DOCTYPE html>\n'+document.documentElement.outerHTML;
    const storage=await storageSnapshot();
    const pre=`window.CREWE_PUBLIC_VIEW_ONLY=true;\nwindow.CREWE_PUBLIC_STORAGE=${safeJson(storage)};\ntry{storageGet=async function(key){return Object.prototype.hasOwnProperty.call(window.CREWE_PUBLIC_STORAGE||{},key)?window.CREWE_PUBLIC_STORAGE[key]:null;};storageSet=async function(){return;};}catch(e){}\n`;
    if(source.includes('loadState();'))source=source.replace('loadState();',pre+'loadState();');
    else source=source.replace('<\/script>',pre+'<\/script>');
    source=source.replace(/<div id="app">[\s\S]*?<\/div>\s*<script>/,'<div id="app"></div>\n<script>');
    source=await inlineGraphicsInSource(source);
    return source;
  }
  async function downloadReadOnlyExport(){
    try{if(typeof saveState==='function')await saveState();}catch(e){}
    const btn=document.getElementById('readonly-export-btn');
    const oldLabel=btn?btn.innerHTML:'';
    if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader-2"></i> Export wird vorbereitet';}
    let html='';
    try{html=await buildReadOnlyHtml();}
    finally{if(btn){btn.disabled=false;btn.innerHTML=oldLabel;}}
    const blob=new Blob([html],{type:'text/html;charset=utf-8'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;a.download=fileNameForExport();
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1500);
  }
  function addReadOnlyExportButton(){
    if(window.CREWE_PUBLIC_VIEW_ONLY)return;
    if(document.getElementById('readonly-export-btn'))return;
    const nav=document.querySelector('.nav');
    if(!nav)return;
    const btn=document.createElement('button');
    btn.id='readonly-export-btn';btn.type='button';btn.className='readonly-export-btn';
    btn.title='Eine eingefrorene Online-Version als HTML-Datei herunterladen';
    btn.innerHTML='<i class="ti ti-world-upload"></i> Online-Export';
    btn.onclick=e=>{e.preventDefault();e.stopPropagation();downloadReadOnlyExport().catch(err=>{console.error(err);alert('Online-Export konnte nicht erstellt werden. Bitte erneut versuchen.');});};
    const importBtn=document.getElementById('sticker-import-btn');
    const addSeason=document.getElementById('add-spread-btn');
    if(importBtn&&importBtn.parentElement===nav)nav.insertBefore(btn,importBtn.nextSibling);
    else if(addSeason&&addSeason.parentElement===nav)nav.insertBefore(btn,addSeason.nextSibling);
    else nav.appendChild(btn);
  }
  function applyPublicFreeze(){
    if(!window.CREWE_PUBLIC_VIEW_ONLY)return;
    document.body.classList.add('public-view');
    document.querySelectorAll('.edit-icon,#global-add-btn,#add-spread-btn,#sticker-import-btn,#readonly-export-btn,#delete-spread-btn,#season-lock-toggle,.season-lock-btn,.sticker-remove-x,.card-remove-overlay,.slot-del,.award-remove-btn,.trophy-add-card,.parking-add,[data-add-slot],.fm-profile-actions,.edit-action-btn,.delete-btn,.manual-history-form,[data-history-edit],[data-history-delete-final],[data-history-delete],.manual-history-delete,.manual-history-add').forEach(el=>el.remove());
    document.querySelectorAll('.slot-empty,.parking-empty,[data-empty],[data-drop],[data-league-index]').forEach(el=>{el.onclick=null;el.ondrop=null;el.ondragover=null;el.ondragenter=null;el.ondragleave=null;});
    document.querySelectorAll('.sticker-card').forEach(card=>{card.setAttribute('draggable','false');card.ondragstart=null;card.ondragend=null;});
    document.querySelectorAll('input,textarea,select').forEach(el=>{el.setAttribute('readonly','readonly');el.setAttribute('tabindex','-1');});
  }
  const prevAttach=attachListeners;
  attachListeners=function(){prevAttach();addReadOnlyExportButton();applyPublicFreeze();};
  if(window.CREWE_PUBLIC_VIEW_ONLY){applyPublicFreeze();setTimeout(applyPublicFreeze,60);setTimeout(applyPublicFreeze,250);}else{addReadOnlyExportButton();}
})();


