// --- User-Patch: größeres Bild + Karten-Popup mit leichter 3D-Drehung ---
(function(){
  const style=document.createElement('style');
  style.textContent=`
    /* Foto auf der kleinen Karte nochmals etwas größer */
    .sticker-card.sticker-card-refmatch .st-red-portrait{
      left:2px!important;
      right:2px!important;
      top:22px!important;
      bottom:44px!important;
    }
    .sticker-card.sticker-card-refmatch .st-red-portrait img{
      transform:scale(1.14)!important;
      transform-origin:center bottom!important;
    }

    /* Popup */
    .card-preview-overlay{
      position:fixed;
      inset:0;
      background:rgba(0,10,26,.84);
      display:flex;
      align-items:center;
      justify-content:center;
      padding:20px;
      z-index:260;
      animation:fadeIn .18s ease forwards;
    }
    .card-preview-box{
      width:min(94vw,520px);
      background:linear-gradient(180deg,#122d57,#0c203d);
      border:1px solid rgba(255,255,255,.12);
      border-radius:22px;
      box-shadow:0 24px 70px rgba(0,0,0,.45);
      padding:18px 18px 16px;
      color:#fff;
      position:relative;
    }
    .card-preview-close{
      position:absolute;
      top:12px;
      right:12px;
      width:42px;
      height:42px;
      border-radius:50%;
      border:2px solid rgba(255,255,255,.88);
      background:#cc2f3a;
      color:#fff;
      display:flex;
      align-items:center;
      justify-content:center;
      cursor:pointer;
      box-shadow:0 8px 20px rgba(0,0,0,.28);
      font-size:22px;
    }
    .card-preview-title{
      font-size:14px;
      font-weight:800;
      letter-spacing:.08em;
      text-transform:uppercase;
      color:rgba(255,255,255,.72);
      text-align:center;
      margin-bottom:12px;
      padding-right:36px;
    }
    .card-preview-stage{
      perspective:1100px;
      display:flex;
      align-items:center;
      justify-content:center;
      min-height:500px;
      user-select:none;
    }
    .card-preview-hint{
      text-align:center;
      font-size:12px;
      color:rgba(255,255,255,.72);
      margin:10px 0 14px;
    }
    .card-preview-stage .sticker-card.sticker-card-refmatch{
      width:min(76vw,320px)!important;
      height:min(calc(min(76vw,320px) * 1.42),455px)!important;
      max-width:320px!important;
      max-height:455px!important;
      min-width:280px!important;
      border-radius:24px!important;
      transform-style:preserve-3d!important;
      transition:transform .18s ease, box-shadow .18s ease!important;
      cursor:grab!important;
      box-shadow:0 20px 40px rgba(0,0,0,.42),0 0 0 1px rgba(255,255,255,.08)!important;
    }
    .card-preview-stage .sticker-card.sticker-card-refmatch.dragging-3d{
      transition:none!important;
      cursor:grabbing!important;
    }
    .card-preview-actions{
      display:flex;
      gap:10px;
      justify-content:center;
      flex-wrap:wrap;
    }
    .card-preview-btn{
      border:none;
      border-radius:12px;
      padding:12px 18px;
      font-size:14px;
      font-weight:800;
      cursor:pointer;
      letter-spacing:.02em;
    }
    .card-preview-btn.primary{background:#d7a93b;color:#071932}
    .card-preview-btn.secondary{background:rgba(255,255,255,.12);color:#fff;border:1px solid rgba(255,255,255,.14)}
    @media (max-width:700px){
      .card-preview-box{padding:14px 14px 14px;border-radius:18px}
      .card-preview-stage{min-height:430px}
      .card-preview-stage .sticker-card.sticker-card-refmatch{width:min(78vw,300px)!important;height:min(calc(min(78vw,300px) * 1.42),426px)!important;min-width:250px!important}
      .card-preview-close{width:38px;height:38px;font-size:20px}
    }
  `;
  document.head.appendChild(style);

  function getStickerDisplayNumber(loc){
    if(!loc||!loc.sticker)return '';
    return loc.sticker.stickerNo || (loc.parking ? (loc.si+1) : slotNumber(loc.cid,loc.si));
  }

  function closeCardPreview(){
    const el=document.getElementById('card-preview-overlay');
    if(el) el.remove();
    document.removeEventListener('keydown', previewEscHandler);
  }
  function previewEscHandler(e){ if(e.key==='Escape') closeCardPreview(); }

  function goToProfileFromPreview(loc){
    closeCardPreview();
    if(loc) setState({showProfile:true,profileTarget:loc});
  }

  function bindPreview3D(card,loc){
    let down=false,startX=0,startY=0,moved=false;
    const maxDeg=5;
    function reset(){
      card.classList.remove('dragging-3d');
      card.style.setProperty('transform','rotateX(0deg) rotateY(0deg) scale(1.02)','important');
    }
    reset();
    card.addEventListener('pointerdown',e=>{
      down=true;moved=false;startX=e.clientX;startY=e.clientY;
      card.classList.add('dragging-3d');
      try{card.setPointerCapture(e.pointerId)}catch(_){ }
    });
    card.addEventListener('pointermove',e=>{
      if(!down) return;
      const dx=e.clientX-startX, dy=e.clientY-startY;
      if(Math.abs(dx)>4||Math.abs(dy)>4) moved=true;
      const rotY=Math.max(-maxDeg,Math.min(maxDeg,(dx/(card.offsetWidth||1))*10));
      const rotX=Math.max(-maxDeg,Math.min(maxDeg,(-dy/(card.offsetHeight||1))*10));
      card.style.setProperty('transform',`rotateX(${rotX}deg) rotateY(${rotY}deg) scale(1.03)`,'important');
    });
    function end(e){
      if(!down) return;
      down=false;
      try{card.releasePointerCapture(e.pointerId)}catch(_){ }
      if(!moved){
        goToProfileFromPreview(loc);
        return;
      }
      reset();
    }
    card.addEventListener('pointerup',end);
    card.addEventListener('pointercancel',end);
    card.addEventListener('lostpointercapture',()=>{ if(down){ down=false; reset(); } });
  }

  function openCardPreview(loc){
    if(!loc||!loc.sticker) return;
    closeCardPreview();
    const overlay=document.createElement('div');
    overlay.id='card-preview-overlay';
    overlay.className='card-preview-overlay';
    const num=getStickerDisplayNumber(loc);
    overlay.innerHTML=`
      <div class="card-preview-box">
        <button class="card-preview-close" type="button" aria-label="Schließen"><i class="ti ti-x"></i></button>
        <div class="card-preview-title">Karte ansehen</div>
        <div class="card-preview-stage">${stickerCardHTML(loc.sticker,num,false)}</div>
        <div class="card-preview-hint">Karte mit gedrückter Maustaste leicht drehen. Klick auf die Karte oder auf den Button öffnet das Profil.</div>
        <div class="card-preview-actions">
          <button class="card-preview-btn primary" type="button" data-preview-profile="1">Zum Profil</button>
          <button class="card-preview-btn secondary" type="button" data-preview-close="1">Schließen</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click',e=>{
      if(e.target===overlay || e.target.closest('[data-preview-close]') || e.target.closest('.card-preview-close')) closeCardPreview();
    });
    const card=overlay.querySelector('.sticker-card');
    if(card){
      card.setAttribute('draggable','false');
      card.ondragstart=null;
      card.ondragend=null;
      bindPreview3D(card,loc);
    }
    const profileBtn=overlay.querySelector('[data-preview-profile]');
    if(profileBtn) profileBtn.onclick=()=>goToProfileFromPreview(loc);
    document.addEventListener('keydown', previewEscHandler);
  }

  const prevAttach=attachListeners;
  attachListeners=function(){
    prevAttach();
    document.querySelectorAll('.sticker-card[data-id]').forEach(card=>{
      card.onclick=e=>{
        if(state.justDropped){state.justDropped=false;return;}
        if(e.target.closest('[data-edit]')) return;
        const loc=findSticker(+card.dataset.id);
        if(loc) openCardPreview(loc);
      };
    });
  };
})();



