// --- User-Patch: Popup-Karte proportional zur kleinen Karte skalieren ---
(function(){
  const style=document.createElement('style');
  style.textContent=`
    .card-preview-stage.proportional{
      min-height:520px!important;
      perspective:1100px!important;
      overflow:visible!important;
      padding:18px 0!important;
    }
    .card-preview-scale-shell{
      width:var(--slot-w)!important;
      height:var(--slot-h)!important;
      min-width:var(--slot-w)!important;
      min-height:var(--slot-h)!important;
      display:flex!important;
      align-items:center!important;
      justify-content:center!important;
      transform-origin:center center!important;
      transform-style:preserve-3d!important;
      will-change:transform!important;
      cursor:grab!important;
      touch-action:none!important;
      transition:transform .18s ease!important;
    }
    .card-preview-scale-shell.dragging-3d{
      transition:none!important;
      cursor:grabbing!important;
    }
    .card-preview-stage.proportional .card-preview-scale-shell .sticker-card.sticker-card-refmatch{
      width:100%!important;
      height:100%!important;
      min-width:0!important;
      min-height:0!important;
      max-width:none!important;
      max-height:none!important;
      border-radius:18px!important;
      transform:none!important;
      transition:none!important;
      cursor:grab!important;
      box-shadow:0 18px 38px rgba(0,0,0,.42),0 0 0 1px rgba(255,255,255,.08)!important;
    }
    .card-preview-stage.proportional .card-preview-scale-shell .sticker-card.sticker-card-refmatch:hover{
      transform:none!important;
    }
    .card-preview-stage.proportional .card-preview-scale-shell.dragging-3d .sticker-card.sticker-card-refmatch{
      cursor:grabbing!important;
    }
    @media (max-width:700px){
      .card-preview-stage.proportional{min-height:430px!important;padding:14px 0!important;}
    }
  `;
  document.head.appendChild(style);

  function previewNumber(loc){
    if(!loc||!loc.sticker)return '';
    return loc.sticker.stickerNo || (loc.parking ? (loc.si+1) : slotNumber(loc.cid,loc.si));
  }
  function closePreview(){
    const el=document.getElementById('card-preview-overlay');
    if(el)el.remove();
    document.removeEventListener('keydown', escClose);
  }
  function escClose(e){if(e.key==='Escape')closePreview();}
  function gotoProfile(loc){
    closePreview();
    if(loc)setState({showProfile:true,profileTarget:loc});
  }
  function fitScale(stage,shell){
    const rect=shell.getBoundingClientRect();
    const baseW=rect.width||parseFloat(getComputedStyle(shell).width)||150;
    const baseH=rect.height||parseFloat(getComputedStyle(shell).height)||205;
    const maxW=Math.min(window.innerWidth*0.76,340);
    const maxH=Math.min(window.innerHeight*0.66,500);
    const scale=Math.max(1,Math.min(maxW/baseW,maxH/baseH));
    shell.dataset.previewScale=String(scale);
    shell.style.setProperty('transform',`scale(${scale}) rotateX(0deg) rotateY(0deg)`,'important');
    stage.style.minHeight=Math.ceil(baseH*scale+32)+'px';
    return scale;
  }
  function bindTilt(shell,loc){
    let down=false,startX=0,startY=0,moved=false,scale=parseFloat(shell.dataset.previewScale||'1')||1;
    const maxDeg=5;
    function reset(){
      scale=parseFloat(shell.dataset.previewScale||String(scale))||scale||1;
      shell.classList.remove('dragging-3d');
      shell.style.setProperty('transform',`scale(${scale}) rotateX(0deg) rotateY(0deg)`,'important');
    }
    shell.addEventListener('pointerdown',e=>{
      down=true;moved=false;startX=e.clientX;startY=e.clientY;
      shell.classList.add('dragging-3d');
      try{shell.setPointerCapture(e.pointerId)}catch(_){ }
    });
    shell.addEventListener('pointermove',e=>{
      if(!down)return;
      const dx=e.clientX-startX,dy=e.clientY-startY;
      if(Math.abs(dx)>4||Math.abs(dy)>4)moved=true;
      const rotY=Math.max(-maxDeg,Math.min(maxDeg,(dx/(shell.offsetWidth||1))*10));
      const rotX=Math.max(-maxDeg,Math.min(maxDeg,(-dy/(shell.offsetHeight||1))*10));
      scale=parseFloat(shell.dataset.previewScale||String(scale))||scale||1;
      shell.style.setProperty('transform',`scale(${scale}) rotateX(${rotX}deg) rotateY(${rotY}deg)`,'important');
    });
    function end(e){
      if(!down)return;
      down=false;
      try{shell.releasePointerCapture(e.pointerId)}catch(_){ }
      if(!moved){gotoProfile(loc);return;}
      reset();
    }
    shell.addEventListener('pointerup',end);
    shell.addEventListener('pointercancel',end);
    shell.addEventListener('lostpointercapture',()=>{if(down){down=false;reset();}});
  }
  function openProportionalCardPreview(loc){
    if(!loc||!loc.sticker)return;
    closePreview();
    const overlay=document.createElement('div');
    overlay.id='card-preview-overlay';
    overlay.className='card-preview-overlay';
    const num=previewNumber(loc);
    overlay.innerHTML=`
      <div class="card-preview-box">
        <button class="card-preview-close" type="button" aria-label="Schließen"><i class="ti ti-x"></i></button>
        <div class="card-preview-title">Karte ansehen</div>
        <div class="card-preview-stage proportional"><div class="card-preview-scale-shell">${stickerCardHTML(loc.sticker,num,false)}</div></div>
        <div class="card-preview-hint">Karte mit gedrückter Maustaste leicht drehen. Klick auf die Karte oder auf den Button öffnet das Profil.</div>
        <div class="card-preview-actions">
          <button class="card-preview-btn primary" type="button" data-preview-profile="1">Zum Profil</button>
          <button class="card-preview-btn secondary" type="button" data-preview-close="1">Schließen</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click',e=>{
      if(e.target===overlay||e.target.closest('[data-preview-close]')||e.target.closest('.card-preview-close'))closePreview();
    });
    const stage=overlay.querySelector('.card-preview-stage');
    const shell=overlay.querySelector('.card-preview-scale-shell');
    const card=overlay.querySelector('.sticker-card');
    if(card){card.setAttribute('draggable','false');card.ondragstart=null;card.ondragend=null;}
    if(stage&&shell){fitScale(stage,shell);bindTilt(shell,loc);}
    const btn=overlay.querySelector('[data-preview-profile]');
    if(btn)btn.onclick=()=>gotoProfile(loc);
    document.addEventListener('keydown',escClose);
  }
  const previousAttach=attachListeners;
  attachListeners=function(){
    previousAttach();
    document.querySelectorAll('.sticker-card[data-id]').forEach(card=>{
      card.onclick=e=>{
        if(state.justDropped){state.justDropped=false;return;}
        if(e.target.closest('[data-edit]'))return;
        const loc=findSticker(+card.dataset.id);
        if(loc)openProportionalCardPreview(loc);
      };
    });
  };
})();



