/* --- nächster ursprünglicher <script>-Block --- */

(function(){
  const style=document.createElement('style');
  style.textContent=`
    .fm-headshot-card,
    .fm-headshot-card-stage,
    .profile-photo-frame{
      cursor:pointer!important;
    }
    .fm-headshot-card-stage .sticker-card,
    .profile-photo-frame{
      transition:transform .14s ease, box-shadow .14s ease!important;
    }
    .fm-headshot-card-stage:hover .sticker-card{
      transform:translateY(-2px) scale(1.01)!important;
    }
    .profile-photo-frame:hover{
      transform:translateY(-2px) scale(1.005)!important;
    }
  `;
  document.head.appendChild(style);

  function findAwardLocByStickerId(id){
    const wanted=String(id||'');
    if(!wanted||!Array.isArray(state.awards)) return null;
    for(let seasonIndex=0; seasonIndex<state.awards.length; seasonIndex++){
      const featured=(state.awards[seasonIndex]&&state.awards[seasonIndex].featured)||{};
      for(const aid of Object.keys(featured)){
        const sticker=featured[aid];
        if(sticker&&String(sticker.id)===wanted){
          return {sticker,award:true,aid,si:0,seasonIndex};
        }
      }
    }
    return null;
  }

  function currentProfileCardLoc(){
    const root=document.querySelector('.fm-profile-modal,.profile-big');
    const card=root&&root.querySelector('.fm-headshot-card-stage .sticker-card[data-id]');
    const selectedId=card&&card.dataset.id ? card.dataset.id : (state.profileSelectedCardId||'');
    if(selectedId){
      const placed=typeof findSticker==='function' ? findSticker(+selectedId) : null;
      if(placed) return placed;
      const award=findAwardLocByStickerId(selectedId);
      if(award) return award;
    }
    return state.profileTarget||null;
  }

  function openProfileCardPreview(e){
    if(e){
      e.preventDefault();
      e.stopPropagation();
    }
    const loc=currentProfileCardLoc();
    if(!loc||!loc.sticker) return;
    if(typeof window.__openPreviewAwardAwareForPatch==='function'){
      window.__openPreviewAwardAwareForPatch(loc);
      return;
    }
    const card=document.querySelector(`.sticker-card[data-id="${loc.sticker.id}"]`);
    if(card) card.click();
  }

  const prevAttach=attachListeners;
  attachListeners=function(){
    prevAttach();

    document.querySelectorAll('.fm-headshot-card,.fm-headshot-card-stage,.profile-photo-frame').forEach(el=>{
      if(el.dataset.profileCardPreviewBound==='1') return;
      el.dataset.profileCardPreviewBound='1';
      el.setAttribute('title','Karte ansehen');
      el.addEventListener('click',openProfileCardPreview,true);
    });

    document.querySelectorAll('.fm-headshot-card-stage .sticker-card').forEach(card=>{
      card.setAttribute('draggable','false');
      card.ondragstart=null;
      card.ondragend=null;
    });
  };
})();


