(function(){
  const style=document.createElement('style');
  style.textContent=`
    .fm-header-info-strip{display:none!important;}
    .fm-profile-modal .fm-info-card{display:block!important;}
    .fm-info-profile-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important;}
    .fm-info-profile-item{min-width:0!important;background:rgba(255,255,255,.045)!important;border:1px solid rgba(255,255,255,.09)!important;border-radius:8px!important;padding:8px 9px!important;}
    .fm-info-profile-item span{display:block!important;font-size:10px!important;color:#aab1c8!important;text-transform:uppercase!important;letter-spacing:.45px!important;margin-bottom:4px!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;}
    .fm-info-profile-item b{display:block!important;color:#fff!important;font-size:13px!important;line-height:1.18!important;font-weight:800!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;}
    .fm-info-profile-sep{height:1px!important;background:rgba(255,255,255,.12)!important;margin:10px 0!important;grid-column:1/-1!important;}
    @media(max-width:760px){.fm-info-profile-grid{grid-template-columns:1fr!important;}}
  `;
  document.head.appendChild(style);

  function esc(v){return String(v ?? '').replace(/[&<>\"]/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m];});}
  function dash(v){const s=String(v ?? '').trim();return s?s:'—';}
  function ageBirth(st){
    let a='—';
    try{a=stickerAge(st,state.spread);}catch(e){}
    const age=a&&a!=='—'?a+' Jahre':'—';
    const bd=st&&st.birthdate?fmtDate(st.birthdate):'';
    return bd?`${age} (${bd})`:age;
  }
  function restoredInfoCard(st){
    const pos=normalizePos(st.position||'');
    const items=[
      ['Alter / Geburtsdatum', ageBirth(st)],
      ['Position', pos||'—'],
      ['Verein', st.club||'Crewe Alexandra'],
      ['Gehalt', st.wage||'—'],
      ['Größe', st.height||'—'],
      ['Persönlichkeit', st.personality||'—'],
      ['Linker Fuß', st.leftFoot||'—'],
      ['Rechter Fuß', st.rightFoot||'—']
    ];
    return `<div class="fm-card fm-info-card"><div class="fm-card-title">Info</div><div class="fm-info-profile-grid">${items.map(function(item,i){
      const sep=i===4?'<div class="fm-info-profile-sep"></div>':'';
      return sep+`<div class="fm-info-profile-item"><span>${esc(item[0])}</span><b>${esc(dash(item[1]))}</b></div>`;
    }).join('')}</div></div>`;
  }

  const previousProfileModal=profileModal;
  profileModal=function(){
    let html=previousProfileModal();
    const target=state.profileTarget||{};
    const st=target&&target.sticker?target.sticker:null;
    if(!html||!st) return html;
    const wrap=document.createElement('div');
    wrap.innerHTML=html;
    wrap.querySelectorAll('.fm-header-info-strip').forEach(function(el){el.remove();});
    const card=wrap.querySelector('.fm-info-card');
    if(card) card.outerHTML=restoredInfoCard(st);
    return wrap.innerHTML;
  };
})();

/* --- nächster ursprünglicher <script>-Block --- */

(function(){
  const style=document.createElement('style');
  style.textContent=`
    /* Linke Spielerprofil-Kachel komplett aus der Uebersicht nehmen */
    .fm-dashboard-clean{grid-template-columns:minmax(0,1fr)!important;}
    .fm-dashboard-clean > .fm-left-panel{display:none!important;}
    .fm-dashboard-clean .fm-mid-panel{grid-column:1!important;}

    /* Nummer im roten Profilbalken ueber den Namen setzen */
    .fm-name-line{display:flex!important;flex-direction:column!important;align-items:flex-start!important;gap:4px!important;}
    .fm-number.fm-number-above{
      order:-1!important;
      display:inline-flex!important;
      align-items:center!important;
      justify-content:center!important;
      min-width:36px!important;
      height:24px!important;
      padding:0 9px!important;
      border-radius:6px!important;
      background:#22a45a!important;
      color:#fff!important;
      font-size:15px!important;
      line-height:1!important;
      font-weight:900!important;
      letter-spacing:.5px!important;
      margin:0!important;
    }
    .fm-birth-under-tags{
      margin-top:7px!important;
      color:#d9d4e7!important;
      font-size:13px!important;
      line-height:1.25!important;
      font-weight:700!important;
    }
    .fm-birth-under-tags span{color:#aaa4bb!important;font-weight:800!important;text-transform:uppercase!important;letter-spacing:.5px!important;font-size:10px!important;margin-right:6px!important;}
    @media(max-width:700px){.fm-birth-under-tags{font-size:12px!important}.fm-number.fm-number-above{height:22px;min-width:32px;font-size:13px}}
  `;
  document.head.appendChild(style);

  function esc(v){return String(v ?? '').replace(/[&<>\"]/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m];});}
  function padNo(v){const s=String(v ?? '').trim();if(!s)return '—';return /^\d+$/.test(s)?s.padStart(3,'0'):s;}
  function isLewis(st){return !!(st&&String(st.name||'').toLowerCase().includes('lewis billington'));}
  function displayPos(st){
    const p=typeof normalizePos==='function'?normalizePos(st&&st.position||''):String(st&&st.position||'');
    return isLewis(st) && p==='IV' ? 'IV / AV' : (isLewis(st) && p==='TW' ? 'IV / AV' : p);
  }
  function birthText(st){
    if(st&&st.birthdate){try{return fmtDate(st.birthdate);}catch(e){return st.birthdate;}}
    return '—';
  }
  function correctLewisPosition(){
    try{
      let changed=false;
      const refs=typeof allStickerRefs==='function'?allStickerRefs():[];
      refs.forEach(function(r){
        const st=r&&r.sticker;
        if(isLewis(st) && (typeof normalizePos==='function'?normalizePos(st.position):st.position)==='TW'){
          st.position='IV';
          changed=true;
        }
      });
      if(changed && typeof saveState==='function') saveState();
    }catch(e){}
  }

  const previousProfileModal=profileModal;
  profileModal=function(){
    correctLewisPosition();
    let html=previousProfileModal();
    const target=state.profileTarget||{};
    const st=target&&target.sticker?target.sticker:null;
    if(!html||!st) return html;
    const number=st.stickerNo||(target.parking?target.si+1:(typeof slotNumber==='function'?slotNumber(target.cid,target.si):''));
    const wrap=document.createElement('div');
    wrap.innerHTML=html;

    /* Spielerprofil-Kachel als Inhalt entfernen, falls sie trotz CSS noch im HTML sitzt */
    wrap.querySelectorAll('.fm-card-title').forEach(function(t){
      if(String(t.textContent||'').trim().toLowerCase()==='spielerprofil'){
        const card=t.closest('.fm-card');
        if(card) card.remove();
      }
    });

    const num=wrap.querySelector('.fm-number');
    if(num){
      num.textContent=padNo(number);
      num.classList.add('fm-number-above');
      const line=wrap.querySelector('.fm-name-line');
      if(line) line.insertBefore(num,line.firstChild);
    }

    const tags=wrap.querySelector('.fm-mini-tags');
    if(tags){
      const first=tags.querySelector('.fm-tag');
      if(first) first.textContent=displayPos(st)||'—';
      const old=tags.parentElement&&tags.parentElement.querySelector('.fm-birth-under-tags');
      if(old) old.remove();
      tags.insertAdjacentHTML('afterend',`<div class="fm-birth-under-tags"><span>Geburtsdatum</span>${esc(birthText(st))}</div>`);
    }

    /* Info-Panel: keine Duplikate fuer Name/Nationalitaet/Status/Wert, nur fehlende bzw. nuetzliche Felder */
    const info=wrap.querySelector('.fm-info-card');
    if(info){
      const items=[
        ['Geburtsdatum', birthText(st)],
        ['Alter', (function(){try{const a=stickerAge(st,state.spread);return a&&a!=='—'?a+' Jahre':'—';}catch(e){return '—';}})()],
        ['Position', displayPos(st)||'—'],
        ['Verein', st.club||'Crewe Alexandra'],
        ['Gehalt', st.wage||'—'],
        ['Größe', st.height||'—'],
        ['Persönlichkeit', st.personality||'—'],
        ['Linker Fuß', st.leftFoot||'—'],
        ['Rechter Fuß', st.rightFoot||'—']
      ];
      info.outerHTML=`<div class="fm-card fm-info-card"><div class="fm-card-title">Info</div><div class="fm-info-profile-grid">${items.map(function(item){return `<div class="fm-info-profile-item"><span>${esc(item[0])}</span><b>${esc(item[1]||'—')}</b></div>`;}).join('')}</div></div>`;
    }
    return wrap.innerHTML;
  };

  /* Beim normalen Rendern ebenfalls die falsche Lewis-Position in der gespeicherten Ansicht korrigieren. */
  const previousRender=render;
  render=function(){correctLewisPosition();return previousRender.apply(this,arguments);};
  try{correctLewisPosition(); if(state.loaded) render();}catch(e){}
})();

