(function(){
  function neutralizePickerCardClicks(root){
    root=root||document;
    root.querySelectorAll('.award-picker-modal .sticker-card, .roster-picker-modal .sticker-card, [data-pick-award-card] .sticker-card, [data-pick-roster-card] .sticker-card').forEach(function(card){
      // Karten im Auswahlfenster sind nur Auswahl-Vorschaubilder. Sie duerfen niemals das Profil/Popout oeffnen.
      card.onclick=null;
      card.setAttribute('draggable','false');
      card.dataset.noProfileOpen='1';
    });
  }

  // Falls ein bereits vorhandener Profil-Handler auf Picker-Karten liegt, ihn gezielt abfangen,
  // ohne die Auswahl am Button zu blockieren: Capture laeuft vor dem alten Card-Handler, der Button
  // bekommt den Klick weiterhin und klebt die Karte ein.
  document.addEventListener('click',function(e){
    var pickerCard=e.target && e.target.closest ? e.target.closest('.award-picker-modal .sticker-card, .roster-picker-modal .sticker-card, [data-pick-award-card] .sticker-card, [data-pick-roster-card] .sticker-card') : null;
    if(!pickerCard) return;
    pickerCard.onclick=null;
    pickerCard.dataset.noProfileOpen='1';
  },true);

  var prevAttach=attachListeners;
  attachListeners=function(){
    prevAttach.apply(this,arguments);
    neutralizePickerCardClicks(document);

    // Zusaetzliche Sicherheit: alle Auswahl-Buttons arbeiten als reine Einkleben-Aktion.
    document.querySelectorAll('[data-pick-award-card], [data-pick-roster-card]').forEach(function(btn){
      if(btn.dataset.noPopoutSelectionBound==='1') return;
      btn.dataset.noPopoutSelectionBound='1';
      btn.addEventListener('click',function(e){
        // Nicht verhindern, dass die vorhandene Auswahl-Logik laeuft; nur verhindern,
        // dass ein Karten-Profil danach noch nach oben durchgereicht wird.
        setTimeout(function(){
          if(state && state.showProfile && (state.showAwardPicker || state.showRosterPicker)){
            setState({showProfile:false,profileTarget:null});
          }
        },0);
      },true);
    });
  };
})();

