/* --- nächster ursprünglicher <script>-Block --- */

(function(){
  const DEFAULT_PLAYER_PHOTO = 'data:image/png;base64,';
  window.DEFAULT_PLAYER_PHOTO = DEFAULT_PLAYER_PHOTO;

  function isBlank(v){ return v === undefined || v === null || String(v).trim() === ''; }
  function isLikelyPlayer(o){
    if(!o || typeof o !== 'object') return false;
    if(!('name' in o)) return false;
    const pos = String(o.position || '').trim().toUpperCase();
    const name = String(o.name || '').trim().toLowerCase();
    if(pos === 'TR' || name === 'trainer') return false;
    return ('position' in o) || ('jerseyNumber' in o) || ('stickerNo' in o) || ('nationality' in o) || ('birthdate' in o) || ('status' in o);
  }

  function applyDefaultPlayerPhotos(root){
    const seen = new WeakSet();
    let changed = false;
    function walk(x){
      if(!x || typeof x !== 'object') return;
      if(seen.has(x)) return;
      seen.add(x);
      if(isLikelyPlayer(x) && isBlank(x.photo)){
        x.photo = DEFAULT_PLAYER_PHOTO;
        changed = true;
      }
      if(Array.isArray(x)){
        x.forEach(walk);
      } else {
        Object.keys(x).forEach(function(k){
          if(k === 'coach') return;
          walk(x[k]);
        });
      }
    }
    walk(root);
    return changed;
  }
  window.applyDefaultPlayerPhotos = applyDefaultPlayerPhotos;

  if(typeof stickerCardHTML === 'function'){
    const oldStickerCardHTML = stickerCardHTML;
    stickerCardHTML = function(st){
      if(st && isLikelyPlayer(st) && isBlank(st.photo)){
        st = Object.assign({}, st, {photo: DEFAULT_PLAYER_PHOTO});
      }
      return oldStickerCardHTML.apply(this, [st].concat(Array.prototype.slice.call(arguments,1)));
    };
  }

  if(typeof saveState === 'function'){
    const oldSaveState = saveState;
    saveState = function(){
      try{ if(window.state) applyDefaultPlayerPhotos(window.state); }catch(e){}
      return oldSaveState.apply(this, arguments);
    };
  }

  if(typeof render === 'function'){
    const oldRender = render;
    render = function(){
      try{ if(window.state) applyDefaultPlayerPhotos(window.state); }catch(e){}
      return oldRender.apply(this, arguments);
    };
  }

  function sweepAndRefresh(delay){
    setTimeout(function(){
      try{
        const changed = window.state ? applyDefaultPlayerPhotos(window.state) : false;
        if(changed && typeof saveState === 'function') saveState();
        if(changed && typeof render === 'function') render();
      }catch(e){}
    }, delay);
  }
  function postImportSweep(){
    sweepAndRefresh(50);
    sweepAndRefresh(400);
    sweepAndRefresh(1000);
  }

  document.addEventListener('change', postImportSweep, true);
  document.addEventListener('click', function(ev){
    const t = ev.target;
    if(t && (t.closest && (t.closest('[data-import]') || t.closest('.import') || t.closest('.save-btn') || t.closest('button')))) postImportSweep();
  }, true);

  postImportSweep();
})();

