    const nat=(typeof getNat==='function') ? getNat(c.nationality||'England') : {c:'ENG'};
    const age=(typeof coachAge==='function') ? coachAge(c,state.spread) : '—';
    const photo=c.photo ? '<img src="'+esc(c.photo)+'" draggable="false">' : missingPhotoIcon();
