(function(){
  function esc(v){
    if(typeof escapeHtml==='function') return escapeHtml(v==null?'':String(v));
    return String(v==null?'':v).replace(/[&<>"']/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m];});
  }
  function coachAsPlayerSticker(){
    try{ if(typeof ensureExtras==='function') ensureExtras(); }catch(e){}
    var c=(window.state&&state.coach) || (typeof defaultCoach==='function' ? defaultCoach() : {});
    return {
      id:'coach-card-sticker',
      stickerNo:'TR',
      name:c.name || 'Trainer',
      nickname:c.name || 'Trainer',
      photo:c.photo || '',
      nationality:c.nationality || 'England',
      birthdate:c.birthdate || '',
      position:'TR',
      jerseyNumber:'TR',
      proDebut:c.takeoverYear || '',
      status:'active'
    };
  }
  function exactTrainerCardHtml(){
    var html='';
    if(typeof stickerCardHTML==='function') html=stickerCardHTML(coachAsPlayerSticker(),'TR',false);
    if(!html){
      html='<div class="sticker-card sticker-card-redesign sticker-card-refmatch"><div class="st-red-top"><div class="st-red-cardno">TR</div><div class="st-red-crest-wrap">'+(typeof clubLogo==='function'?clubLogo(20):'')+'<div class="st-red-jersey">TR</div></div></div><div class="st-red-portrait"><div class="st-red-photo-placeholder"><i class="ti ti-user-star"></i></div></div><div class="st-red-lower"><div class="st-red-name"><span>Trainer</span></div><div class="st-red-bottom"><div class="st-red-meta left"><span class="st-red-meta-label">Alter</span><span class="st-red-meta-value">—</span></div><div class="st-red-meta"><span class="st-red-meta-label">Position</span><span class="st-red-meta-value">TR</span></div><div class="st-red-meta right"><span class="st-red-meta-label">Land</span><span class="st-red-meta-value nat">—</span></div></div></div></div>';
    }
    html=String(html)
      .replace(/<div class="sticker-card([^"]*)"([^>]*)>/, '<div id="coach-card" class="sticker-card coach-sticker-mini trainer-sticker-card$1" title="Trainer-Profil öffnen" draggable="false">')
      .replace(/\sdata-id="[^"]*"/g,'')
      .replace(/\sdraggable="true"/g,' draggable="false"')
      .replace(/<div class="edit-icon"[\s\S]*?<\/div>/g,'')
      .replace(/<div class="status-icon"[\s\S]*?<\/div>/g,'')
      .replace(/<div class="sold-card-note"[\s\S]*?<\/div>/g,'');
    return html;
  }
  function wireCoachCard(){
    var card=document.getElementById('coach-card');
    if(!card) return;
    card.onclick=function(e){
      e.preventDefault();
      e.stopPropagation();
      if(typeof setState==='function') setState({showCoachProfile:true,showCoachEdit:false});
    };
    card.setAttribute('draggable','false');
  }
  window.renderCoachCard=function(){ return exactTrainerCardHtml(); };
  var oldAttach=window.attachListeners;
  if(typeof oldAttach==='function'){
    window.attachListeners=function(){ oldAttach.apply(this,arguments); wireCoachCard(); };
  }
  setTimeout(function(){ try{ if(typeof render==='function') render(); else wireCoachCard(); }catch(e){ wireCoachCard(); } },0);
})();

/* --- nächster ursprünglicher <script>-Block --- */

(function(){
  function esc(v){
    try{return typeof escapeHtml==='function'?escapeHtml(v==null?'':String(v)):String(v==null?'':v).replace(/[&<>\"']/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m];});}
    catch(e){return String(v==null?'':v);}
  }
  function getCoach(){
    try{ if(typeof ensureExtras==='function') ensureExtras(); }catch(e){}
    return (window.state && state.coach) || {name:'Trainer',photo:null,nationality:'England',birthdate:'',takeoverYear:'2025'};
  }
  function coachAgeLocal(c){
    try{ if(typeof coachAge==='function') return coachAge(c,state.spread); }catch(e){}
    if(!c || !c.birthdate) return '—';
    var y=parseInt(String(c.birthdate).slice(0,4),10); if(!y) return '—';
    return String((2026+(state&&state.spread||0))-y);
  }
  function natCode(c){
    try{ var n=typeof getNat==='function'?getNat(c.nationality||'England'):null; if(n&&n.c) return n.c; }catch(e){}
    return String(c.nationality||'ENG').slice(0,3).toUpperCase();
  }
  function logoHtml(){
    try{return typeof clubLogo==='function'?clubLogo(40):'';}catch(e){return '';}
  }
  function trainerScreenshotHtml(){
    var c=getCoach();
    var name=esc(c.name||'Trainer');
    var age=esc(coachAgeLocal(c)||'—');
    var land=esc(natCode(c)||'ENG');
    var photo=c.photo?'<img src="'+esc(c.photo)+'" draggable="false" alt="Trainerfoto">':'<div class="trainer-silhouette" aria-hidden="true"></div>';
    return '<div id="coach-card" class="coach-sticker-mini trainer-screenshot-card" title="Trainer-Profil öffnen" draggable="false">'
      + '<div class="trainer-card-no">TR</div>'
      + '<div class="trainer-card-crest">'+logoHtml()+'</div>'
      + '<div class="trainer-card-season">'+esc(String((state&&state.spread||0)+1))+'</div>'
      + '<div class="trainer-card-photo">'+photo+'</div>'
      + '<div class="trainer-card-name">'+name+'</div>'
      + '<div class="trainer-card-meta">'
      + '<div><span class="trainer-meta-label">Alter</span><span class="trainer-meta-value">'+age+'</span></div>'
      + '<div><span class="trainer-meta-label">Position</span><span class="trainer-meta-value">TR</span></div>'
      + '<div><span class="trainer-meta-label">Land</span><span class="trainer-meta-value">'+land+'</span></div>'
      + '</div></div>';
  }
  function replaceCoachCard(){
    var card=document.getElementById('coach-card');
    if(!card) return;
    if(!card.classList.contains('trainer-screenshot-card')) card.outerHTML=trainerScreenshotHtml();
    card=document.getElementById('coach-card');
    if(!card) return;
    card.onclick=function(e){ e.preventDefault(); e.stopPropagation(); if(typeof setState==='function') setState({showCoachProfile:true,showCoachEdit:false}); };
    card.setAttribute('draggable','false');
  }
  window.renderCoachCard=function(){ return trainerScreenshotHtml(); };
  var previousAttach=window.attachListeners;
  if(typeof previousAttach==='function'){
    window.attachListeners=function(){ previousAttach.apply(this,arguments); replaceCoachCard(); };
  }
  setTimeout(function(){ try{replaceCoachCard();}catch(e){} },0);
})();

