/* --- nächster ursprünglicher <script>-Block --- */

(function(){
  var RESET_MARKER_KEY='crewe-user-card-reset-2026-05-19-v3';
  var RESET_VALUE='done';
  var CARD_STORE_KEYS=[
    'crewe-categorized-v1','crewe-sticker-archive-v2','crewe-season-pages-v1','crewe-extra-v2',
    'crewe-auto-league-history-v1','crewe-auto-league-history-reset-v1','crewe-league-history-v1',
    'crewe-league-history-vorsaison-v3','crewe-final-profile-history-v1','crewe-season-locks-v1'
  ];
  var AWARD_IDS=['topScorer','mostScorers','playerSeason','u19PlayerSeason','goalSeason'];

  function copy(o){try{return JSON.parse(JSON.stringify(o||{}));}catch(e){return Object.assign({},o||{});}}
  function isFilled(v){return v!==undefined&&v!==null&&String(v).trim()!=='';}
  function asInt(v){var n=parseInt(v,10);return Number.isFinite(n)?n:0;}
  function blankAwardsObj(){var f={};AWARD_IDS.forEach(function(id){f[id]=null;});return {featured:f,trophies:[null]};}
  function rootProfileId(st){
    if(!st)return null;
    return st.playerProfileId||st.linkedPlayerId||st.awardSourceId||st.seasonCloneOf||st.originalId||st.cloneOf||st.id||null;
  }
  function normalizeIdentity(st){
    if(!st)return st;
    var rid=rootProfileId(st);
    if(rid!==null&&rid!==undefined&&rid!==''){
      st.playerProfileId=rid;
      st.linkedPlayerId=rid;
    } else if(st.id!==undefined&&st.id!==null&&st.id!=='') {
      st.playerProfileId=st.id;
      st.linkedPlayerId=st.id;
    }
    return st;
  }
  function allCardsRaw(){
    var out=[];
    try{(state.spreads||[]).forEach(function(sp){CATEGORIES.forEach(function(c){((sp.categories&&sp.categories[c.id])||[]).forEach(function(s){if(s)out.push(s);});});});}catch(e){}
    try{(state.parking||[]).forEach(function(s){if(s)out.push(s);});}catch(e){}
    try{(state.stickerArchive||[]).forEach(function(s){if(s)out.push(s);});}catch(e){}
    try{if(Array.isArray(state.awards))state.awards.forEach(function(aw){var f=aw&&aw.featured?aw.featured:{};Object.keys(f).forEach(function(k){if(f[k])out.push(f[k]);});});}catch(e){}
    return out;
  }
  function nextIdFinal(){
    var max=0;allCardsRaw().forEach(function(s){max=Math.max(max,asInt(s&&s.id));});
    var n=Math.max(max+1,asInt(state.nextId||1));
    state.nextId=n+1;return n;
  }
  function nextStickerNoFinal(){
    var max=0;allCardsRaw().forEach(function(s){max=Math.max(max,asInt(s&&s.stickerNo));});
    var n=Math.max(max+1,asInt(state.nextStickerNo||1));
    state.nextStickerNo=n+1;return n;
  }
  function makeNewCardInstance(src,extra){
    var original=src||{};
    var st=copy(original);
    var rid=rootProfileId(original)||original.id||null;
    st.id=nextIdFinal();
    st.stickerNo=nextStickerNoFinal();
    st.cardInstance=true;
    st.originalId=original.id||st.originalId||null;
    st.seasonCloneOf=rid||original.id||null;
    st.playerProfileId=rid||original.id||st.id;
    st.linkedPlayerId=st.playerProfileId;
    if(extra)Object.assign(st,extra);
    if(typeof normalizeSticker==='function')st=normalizeSticker(st);
    return normalizeIdentity(st);
  }
  window.makeNewCardInstance=makeNewCardInstance;

  // Jede neue Saison-Kopie bekommt ab jetzt eine eigene Sticker-ID und eigene Nummer.
  cloneSeasonSticker=function(sticker){
    if(!sticker)return null;
    return makeNewCardInstance(sticker,{copiedFromSeason:state.spread,seasonClone:true});
  };

  // Normale/neu importierte Spieler bekommen eine stabile Profil-ID. Karteninstanzen bleiben trotzdem eindeutig.
  var prevNormalize=normalizeSticker;
  normalizeSticker=function(s){
    var st=typeof prevNormalize==='function'?prevNormalize(s):(s||null);
    return normalizeIdentity(st);
  };

  function clearCardsInMemory(){
    state.spreads=[typeof makeSpread==='function'?makeSpread(1):{id:1,categories:{keeper:[null],defenders:[null],midfield:[null],forwards:[null]}}];
    state.parking=Array(20).fill(null);
    state.stickerArchive=[];
    state.awards=[blankAwardsObj()];
    state.leagueSeasons=[{leagueIndex:3,years:{},places:{}}];
    state.leagueHistoryEntries=[];
    state.autoLeagueHistory=[];
    state.seasonLocked=[];
    state.spread=0;state.seasonPage=0;
    state.nextId=1;state.nextStickerNo=1;
    state.showAdd=false;state.addTarget=null;state.showEdit=false;state.editTarget=null;
    state.showProfile=false;state.profileTarget=null;state.profileSelectedCardId=null;state.profileClickedCardId=null;state.__exactClickedProfileLoc=null;
    state.showAwardPicker=false;state.awardPickerTarget=null;state.showRosterPicker=false;state.rosterPickerTarget=null;
    state.showTrophyAdd=false;state.showTrophyEdit=false;state.trophyTarget=null;
    try{if(typeof tidyCategoryPlaceholders==='function')tidyCategoryPlaceholders();}catch(e){}
  }
  async function storageClearCardData(){
    for(var i=0;i<CARD_STORE_KEYS.length;i++){
      try{await storageSet(CARD_STORE_KEYS[i],'');}catch(e){}
      try{if(window.localStorage)localStorage.removeItem(CARD_STORE_KEYS[i]);}catch(e){}
    }
  }
  async function runOneTimeReset(){
    var done='';
    try{done=await storageGet(RESET_MARKER_KEY);}catch(e){}
    if(done===RESET_VALUE)return false;
    await storageClearCardData();
    clearCardsInMemory();
    try{await storageSet(RESET_MARKER_KEY,RESET_VALUE);}catch(e){}
    try{if(typeof saveState==='function')await saveState();}catch(e){}
    try{if(typeof render==='function')render();}catch(e){}
    return true;
  }
  function waitForLoaded(){
    var tries=0;
    var timer=setInterval(function(){
      tries++;
      if((state&&state.loaded)||tries>120){
        clearInterval(timer);
        runOneTimeReset();
      }
    },60);
  }
  waitForLoaded();

  // Reserve-Album: keine Duplikate per Name zusammenfassen, sondern jede Karteninstanz separat behandeln.
  function cardKey(st){return String(st&&st.id?st.id:(Math.random()+''));}
  function collectAllInstances(){
    var map=new Map();
    function add(s){if(!s)return;var st=normalizeIdentity(typeof normalizeSticker==='function'?normalizeSticker(copy(s)):copy(s));map.set(cardKey(st),st);}
    try{(state.stickerArchive||[]).forEach(add);}catch(e){}
    try{(state.spreads||[]).forEach(function(sp){CATEGORIES.forEach(function(c){((sp.categories&&sp.categories[c.id])||[]).forEach(add);});});}catch(e){}
    try{(state.parking||[]).forEach(add);}catch(e){}
    try{if(Array.isArray(state.awards))state.awards.forEach(function(aw){var f=aw&&aw.featured?aw.featured:{};Object.keys(f).forEach(function(k){add(f[k]);});});}catch(e){}
    return Array.from(map.values()).sort(function(a,b){return String(a.name||'').localeCompare(String(b.name||''),'de',{sensitivity:'base'}) || asInt(a.stickerNo)-asInt(b.stickerNo);});
  }
  function currentRosterExactIds(){
    var ids=new Set();
    try{var sp=currentSpread();CATEGORIES.forEach(function(c){((sp.categories&&sp.categories[c.id])||[]).forEach(function(s){if(s&&s.id)ids.add(String(s.id));});});}catch(e){}
    return ids;
  }
  renderParkingAlbum=function(){
    var roster=currentRosterExactIds();
    var all=collectAllInstances();
    var visible=all.filter(function(s){return s && !roster.has(String(s.id));});
    state.stickerArchive=all;
    state.parking=visible.concat([null]);
    if(!state.parkingOpen){
      return '<button id="parking-toggle" class="parking-closed" title="Reserve-Album öffnen"><div class="parking-cover-content">'+clubLogo(42)+'<div class="parking-cover-title">Reserve<br>Album</div><div class="parking-cover-sub">'+visible.length+' Sticker</div></div></button>';
    }
    var slots=visible.map(function(sticker,si){return '<div class="parking-slot slot-teal" data-parking="1" data-si="'+si+'" data-drop="1">'+stickerCardHTML(sticker,sticker.stickerNo||si+1,state.newKey===('parking-'+si))+'</div>';}).join('');
    var empty='<div class="reserve-empty-state">Alle Karteninstanzen dieser Saison sind eingeklebt</div>';
    return '<div class="parking-panel"><div class="parking-page"><div class="parking-head"><div class="parking-title">'+clubLogo(34)+'<div><div>Reserve-Album</div><div class="reserve-archive-note">'+visible.length+' freie Sticker · jede Karte behält ihre eigene Nummer</div></div></div><div class="parking-actions"><button id="parking-close" class="parking-close"><i class="ti ti-chevron-down"></i></button></div></div><div class="parking-grid reserve-archive-grid">'+(slots||empty)+'</div></div></div>';
  };

  // Profilkarte oben links: Klick öffnet immer die aktuell oben angezeigte Karteninstanz.
  function locateCardInstanceById(id){
    var sid=String(id||'');
    if(!sid)return null;
    try{if(typeof findSticker==='function'){var loc=findSticker(Number(sid));if(loc&&loc.sticker)return loc;}}catch(e){}
    try{if(Array.isArray(state.awards))for(var seasonIndex=0;seasonIndex<state.awards.length;seasonIndex++){var aw=state.awards[seasonIndex]||{},f=aw.featured||{};for(var aid in f){var s=f[aid];if(s&&String(s.id)===sid)return{sticker:s,award:true,aid:aid,si:0,seasonIndex:seasonIndex};}}}catch(e){}
    var found=collectAllInstances().find(function(s){return String(s.id)===sid;});
    return found?{sticker:found,archive:true,si:0}:null;
  }
  var prevAttachFinal=attachListeners;
  attachListeners=function(){
    prevAttachFinal.apply(this,arguments);
    document.querySelectorAll('[data-profile-card-choice]').forEach(function(btn){
      btn.onclick=function(e){
        e.preventDefault();e.stopPropagation();
        var loc=locateCardInstanceById(btn.dataset.profileCardChoice);
        if(loc&&loc.sticker){
          state.profileSelectedCardId=String(loc.sticker.id||'');
          state.profileClickedCardId=String(loc.sticker.id||'');
          state.__exactClickedProfileLoc=loc;
          state.fmActiveTab='career';
          setState({showProfile:true,profileTarget:loc});
        }
      };
    });
    document.querySelectorAll('.fm-headshot-card-stage,.fm-headshot-card').forEach(function(el){
      el.onclick=function(e){
        e.preventDefault();e.stopPropagation();
        var card=el.querySelector('.sticker-card[data-id]') || (el.matches&&el.matches('.sticker-card[data-id]')?el:null);
        var loc=locateCardInstanceById(card&&card.dataset.id?card.dataset.id:(state.profileSelectedCardId||'')) || state.profileTarget;
        if(loc&&loc.sticker&&window.__openPreviewAwardAwareForPatch)window.__openPreviewAwardAwareForPatch(loc);
      };
    });
  };
})();

/* --- nächster ursprünglicher <script>-Block --- */

(function(){
  function has(v){return v!==undefined && v!==null && String(v).trim()!=='';}
  function normKey(k){
    return String(k||'')
      .replace(/Ã¤/g,'ä').replace(/Ã¶/g,'ö').replace(/Ã¼/g,'ü').replace(/ÃŸ/g,'ß')
      .replace(/�/g,'')
      .toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
      .replace(/ß/g,'ss')
      .replace(/[^a-z0-9]/g,'');
  }
  function rawSources(st){
    var rows=[];
    if(st&&st.rawRow)rows.push(st.rawRow);
    if(st&&st.importSnapshot&&st.importSnapshot.rawRow)rows.push(st.importSnapshot.rawRow);
    if(st&&Array.isArray(st.importSnapshots)){
      st.importSnapshots.forEach(function(s){if(s&&s.rawRow)rows.push(s.rawRow);});
    }
    if(st&&st.attrs)rows.push(st.attrs);
    return rows;
  }
  function pickRaw(st,aliases){
    var wanted=aliases.map(normKey);
    var rows=rawSources(st);
    for(var r=0;r<rows.length;r++){
      var row=rows[r]||{};
      var entries=Object.entries(row);
      for(var i=0;i<entries.length;i++){
        var nk=normKey(entries[i][0]);
        if(wanted.indexOf(nk)>=0 && has(entries[i][1]))return String(entries[i][1]).trim();
      }
      for(var j=0;j<entries.length;j++){
        var key=normKey(entries[j][0]);
        if(!has(entries[j][1]))continue;
        for(var a=0;a<wanted.length;a++){
          var w=wanted[a];
          if(w && (key.indexOf(w)>=0 || w.indexOf(key)>=0))return String(entries[j][1]).trim();
        }
      }
    }
    return '';
  }
  function hydrateProfileCsvFields(st){
    if(!st)return st;
    if(!has(st.personality)){
      st.personality=pickRaw(st,['personality','persoenlichkeit','personlichkeit','persnlichkeit','persoenl','personl','persnl','pers']);
    }
    if(!has(st.reputation)){
      st.reputation=pickRaw(st,['reputation','ansehen','ruf']);
    }
    if(!has(st.leftFoot)){
      st.leftFoot=pickRaw(st,['leftfoot','linkerfuss','linkerfus','linkerfu','lifuss','lifus','lifu','linksfuss','linksfu']);
    }
    if(!has(st.rightFoot)){
      st.rightFoot=pickRaw(st,['rightfoot','rechterfuss','rechterfus','rechterfu','refuss','refus','refu','rechtsfuss','rechtsfu']);
    }
    return st;
  }
  window.hydrateProfileCsvFields=hydrateProfileCsvFields;

  var prevNormalizeSticker=window.normalizeSticker;
  window.normalizeSticker=function(s){
    var st=typeof prevNormalizeSticker==='function'?prevNormalizeSticker(s):(s||null);
    return hydrateProfileCsvFields(st);
  };

  var prevProfileModal=profileModal;
  profileModal=function(){
    try{
      var st=state&&state.profileTarget&&state.profileTarget.sticker;
      if(st)hydrateProfileCsvFields(st);
    }catch(e){}
    return prevProfileModal.apply(this,arguments);
  };

  var prevRender=render;
  render=function(){
    try{
      if(typeof allStickerRefs==='function'){
        allStickerRefs().forEach(function(r){if(r&&r.sticker)hydrateProfileCsvFields(r.sticker);});
      }
    }catch(e){}
    return prevRender.apply(this,arguments);
  };
})();

/* --- Performance patch: profile modal fast path --- */
(function(){
  var fullSetState=setState;
  var profileHtmlCache=new WeakMap();
  var openKeys={
    showProfile:1,profileTarget:1,profileSelectedCardId:1,profileClickedCardId:1,
    __exactClickedProfileLoc:1,fmActiveTab:1,showAwardPicker:1,awardPickerTarget:1,
    showRosterPicker:1,rosterPickerTarget:1,addTarget:1,showEdit:1,editTarget:1
  };
  var closeKeys={
    showProfile:1,profileTarget:1,profileSelectedCardId:1,profileClickedCardId:1,
    __exactClickedProfileLoc:1,confirmDelSticker:1,showEdit:1,editTarget:1
  };

  function patchObject(patch){
    return patch && typeof patch==='object' && !Array.isArray(patch);
  }

  function onlyKnownKeys(patch,known){
    return Object.keys(patch).every(function(k){return known[k];});
  }

  function profileOverlayOf(el){
    return !!(el && el.querySelector && (
      el.querySelector('#close-profile-btn') ||
      el.querySelector('.fm-profile-modal') ||
      el.querySelector('.profile-big')
    ));
  }

  function removeProfileOverlay(){
    document.querySelectorAll('.modal-overlay').forEach(function(el){
      if(profileOverlayOf(el)) el.remove();
    });
  }

  function removePickerOverlays(){
    document.querySelectorAll('.modal-overlay').forEach(function(el){
      if(el.querySelector && (el.querySelector('.award-picker-modal') || el.querySelector('.roster-picker-modal'))){
        el.remove();
      }
    });
  }

  function currentProfileCacheKey(target){
    var st=target && target.sticker;
    if(!st || typeof st!=='object') return '';
    return [
      st.id || '',
      st.stickerNo || '',
      st.name || '',
      st.nickname || '',
      st.jerseyNumber || '',
      st.position || '',
      st.status || '',
      st.photo ? String(st.photo).length : 0,
      state.spread || 0,
      state.fmActiveTab || '',
      state.profileSelectedCardId || '',
      state.profileClickedCardId || '',
      target.aid || target.award || '',
      target.parking ? 'parking' : '',
      target.archive ? 'archive' : ''
    ].join('|');
  }

  function profileHtmlFast(){
    var target=state.profileTarget;
    var st=target && target.sticker;
    var key=currentProfileCacheKey(target);
    if(st && key){
      var cached=profileHtmlCache.get(st);
      if(cached && cached.key===key) return cached.html;
    }
    var html=profileModal();
    if(typeof optimizeAlbumHTML==='function') html=optimizeAlbumHTML(html);
    if(st && key) profileHtmlCache.set(st,{key:key,html:html});
    return html;
  }

  function mountProfileOverlay(){
    var app=document.getElementById('app') || document.body;
    if(!app || !state.showProfile || !state.profileTarget) return;
    removePickerOverlays();
    removeProfileOverlay();
    app.insertAdjacentHTML('beforeend',profileHtmlFast());
    if(typeof attachListeners==='function') attachListeners();
    if(typeof initLazyImages==='function') initLazyImages();
  }

  function isProfileOpenOnly(patch){
    if(!patchObject(patch) || patch.showProfile!==true || !patch.profileTarget) return false;
    if(patch.showEdit===true) return false;
    return onlyKnownKeys(patch,openKeys);
  }

  function isProfileCloseOnly(patch){
    if(!patchObject(patch) || patch.showProfile!==false) return false;
    if(patch.showEdit===true) return false;
    if(patch.confirmDelSticker===true) return false;
    return onlyKnownKeys(patch,closeKeys);
  }

  setState=function(patch){
    if(typeof patch==='function') return fullSetState.apply(this,arguments);
    if(isProfileOpenOnly(patch)){
      Object.assign(state,patch);
      mountProfileOverlay();
      return;
    }
    if(isProfileCloseOnly(patch)){
      Object.assign(state,patch);
      removeProfileOverlay();
      return;
    }
    return fullSetState.apply(this,arguments);
  };
})();

/* --- Final fix: remove pasted roster card into reserve album --- */
(function(){
  function cloneForReserve(sticker){
    if(!sticker) return null;
    try{return typeof normalizeSticker==='function' ? normalizeSticker({...sticker}) : {...sticker};}
    catch(_){return {...sticker};}
  }

  function reserveArchiveUpsert(sticker){
    const st=cloneForReserve(sticker);
    if(!st || st.id===undefined || st.id===null || st.id==='') return;
    if(!Array.isArray(state.stickerArchive)) state.stickerArchive=[];
    const sid=String(st.id);
    const i=state.stickerArchive.findIndex(function(x){return x && String(x.id)===sid;});
    if(i>=0) state.stickerArchive[i]={...state.stickerArchive[i],...st};
    else state.stickerArchive.push(st);
  }

  function findRosterSlotFromButton(btn){
    const slot=btn && btn.closest ? btn.closest('[data-cid][data-si]') : null;
    if(slot && !slot.closest('.parking-slot')){
      const cid=slot.dataset.cid;
      const si=parseInt(slot.dataset.si||'0',10);
      const sp=typeof currentSpread==='function' ? currentSpread() : null;
      const arr=sp && sp.categories && sp.categories[cid];
      if(arr && arr[si]) return {arr:arr,si:si,sticker:arr[si],slot:slot,cid:cid};
    }

    const card=btn && btn.closest ? btn.closest('.sticker-card[data-id]') : null;
    const sid=card && card.dataset ? String(card.dataset.id||'') : '';
    if(!sid) return null;
    const sp=typeof currentSpread==='function' ? currentSpread() : null;
    if(sp && sp.categories){
      for(const c of CATEGORIES){
        const arr=sp.categories[c.id]||[];
        for(let si=0;si<arr.length;si++){
          const st=arr[si];
          if(st && String(st.id)===sid) return {arr:arr,si:si,sticker:st,slot:card.closest('[data-cid][data-si]'),cid:c.id};
        }
      }
    }
    return null;
  }

  function emptySlotHTML(cid){
    const cat=(typeof CATEGORIES!=='undefined' ? CATEGORIES.find(function(c){return c.id===cid;}) : null) || {};
    const title=cat.title || 'Sticker';
    return '<i class="ti ti-plus" style="font-size:clamp(22px,2.2vw,31px)"></i><span class="slot-cat">'+title+'</span>';
  }

  function makeEmptySlotElement(cid,si){
    const el=document.createElement('div');
    el.className='slot slot-empty';
    el.dataset.cid=cid;
    el.dataset.si=String(si);
    el.dataset.empty='1';
    el.innerHTML=emptySlotHTML(cid);
    el.onclick=function(e){
      if(e.target.closest('[data-del-slot]')) return;
      const t={cid:el.dataset.cid,si:parseInt(el.dataset.si||'0',10)};
      if(typeof setState==='function') setState({showAdd:true,addTarget:t});
    };
    return el;
  }

  function reindexCategoryDom(section){
    if(!section) return;
    section.querySelectorAll('[data-cid][data-si]').forEach(function(el,idx){
      el.dataset.si=String(idx);
    });
  }

  function paintCompactedSlots(loc){
    const slot=loc && loc.slot;
    if(!slot || !slot.dataset) return;
    const section=slot.closest('[data-cat]');
    const grid=section && section.querySelector('.sticker-grid');
    slot.remove();
    if(grid && !grid.querySelector('.slot-empty[data-empty="1"]')){
      grid.appendChild(makeEmptySlotElement(loc.cid,grid.children.length));
    }
    reindexCategoryDom(section);
  }

  function refreshSmallCounts(){
    try{
      const sp=typeof currentSpread==='function' ? currentSpread() : null;
      if(!sp) return;
      CATEGORIES.forEach(function(c){
        const section=document.querySelector('[data-cat="'+c.id+'"]');
        const meta=section && section.querySelector('.category-meta');
        const filled=(sp.categories[c.id]||[]).filter(Boolean).length;
        if(meta) meta.textContent=filled+' Spieler · 1 freier Platzhalter';
      });
      const filled=CATEGORIES.reduce(function(t,c){return t+(sp.categories[c.id]||[]).filter(Boolean).length;},0);
      const total=CATEGORIES.reduce(function(t,c){return t+(sp.categories[c.id]||[]).length;},0);
      const counter=document.querySelector('.counter');
      if(counter) counter.textContent=filled+' von '+total+' Aufkleber-Plätzen in Saison '+((state.spread||0)+1)+' belegt';
    }catch(_){}
  }

  function scheduleReserveSave(){
    const work=function(){try{if(typeof saveState==='function') saveState();}catch(_){}};
    if('requestIdleCallback' in window) window.requestIdleCallback(work,{timeout:2500});
    else setTimeout(work,250);
  }

  function scheduleAfterPaint(work){
    if(typeof requestAnimationFrame==='function'){
      requestAnimationFrame(function(){setTimeout(work,0);});
    } else {
      setTimeout(work,0);
    }
  }

  function isAlbumRosterRemove(btn){
    if(!btn || !btn.closest) return false;
    if(btn.closest('.parking-slot,.parking-panel,.card-preview-overlay,.modal-overlay,.profile-card-choice,.award-picker-modal,.roster-picker-modal')) return false;
    if(btn.closest('[data-trophy="1"],[data-award-cat],[data-award]')) return false;
    return !!findRosterSlotFromButton(btn);
  }

  function moveRosterButtonToReserve(btn,e){
    if(e){
      e.preventDefault();
      e.stopPropagation();
      if(e.stopImmediatePropagation) e.stopImmediatePropagation();
    }
    const loc=findRosterSlotFromButton(btn);
    if(!loc || !loc.sticker) return false;
    const movedSticker=cloneForReserve(loc.sticker);
    loc.arr.splice(loc.si,1);
    if(!loc.arr.length || loc.arr[loc.arr.length-1]) loc.arr.push(null);
    paintCompactedSlots(loc);
    refreshSmallCounts();
    state.showProfile=false;
    state.profileTarget=null;
    state.confirmDelSticker=false;
    state.showEdit=false;
    state.editTarget=null;
    scheduleAfterPaint(function(){
      reserveArchiveUpsert(movedSticker);
      if(Array.isArray(state.parking) && movedSticker && movedSticker.id!==undefined && !state.parking.some(function(s){return s && String(s.id)===String(movedSticker.id);})){
        const empty=state.parking.findIndex(function(s){return !s;});
        if(empty>=0) state.parking[empty]=movedSticker;
        else state.parking.push(movedSticker);
      }
      scheduleReserveSave();
    });
    return true;
  }

  document.addEventListener('click',function(e){
    const btn=e.target && e.target.closest ? e.target.closest('.sticker-remove-x,.card-remove-overlay') : null;
    if(!isAlbumRosterRemove(btn)) return;
    moveRosterButtonToReserve(btn,e);
  },true);

  const previousAttachReserveMove=attachListeners;
  attachListeners=function(){
    previousAttachReserveMove.apply(this,arguments);
    document.querySelectorAll('.sticker-remove-x,.card-remove-overlay').forEach(function(btn){
      if(!isAlbumRosterRemove(btn)) return;
      btn.onclick=function(e){moveRosterButtonToReserve(btn,e);};
      btn.title='Sticker ins Reserve-Album verschieben';
    });
  };
})();

/* --- True final profile cleanup: no import history/development in career tab --- */
(function(){
  function cleanCareerExtrasFinal(root){
    if(!root || !root.querySelectorAll) return;
    root.querySelectorAll('.player-development-block,.season-data-dot,.fm-import-history-table,.fm-import-raw-grid').forEach(function(el){el.remove();});
    root.querySelectorAll('.fm-season-title').forEach(function(title){
      var text=String(title.textContent||'');
      if(text.indexOf('Import-Verlauf')===-1 && text.indexOf('Rohdaten letzter Import')===-1) return;
      var prev=title.previousElementSibling;
      if(prev && prev.classList && prev.classList.contains('fm-season-divider')) prev.remove();
      var next=title.nextElementSibling;
      while(next && (
        (next.classList && next.classList.contains('fm-import-history-table')) ||
        (next.classList && next.classList.contains('fm-import-raw-grid')) ||
        (next.classList && next.classList.contains('fm-card') && text.indexOf('Import-Verlauf')!==-1)
      )){
        var current=next;
        next=next.nextElementSibling;
        current.remove();
      }
      title.remove();
    });
  }

  function cleanProfileHtmlFinal(html){
    try{
      var template=document.createElement('template');
      template.innerHTML=String(html||'');
      cleanCareerExtrasFinal(template.content);
      return template.innerHTML;
    }catch(_){return html;}
  }

  if(typeof profileModal==='function'){
    var previousProfileModalCleanFinal=profileModal;
    profileModal=function(){
      return cleanProfileHtmlFinal(previousProfileModalCleanFinal.apply(this,arguments));
    };
  }

  var style=document.createElement('style');
  style.textContent='.player-development-block,.season-data-dot,.fm-import-history-table,.fm-import-raw-grid{display:none!important}';
  document.head.appendChild(style);

  var previousAttachCleanFinal=attachListeners;
  attachListeners=function(){
    previousAttachCleanFinal.apply(this,arguments);
    cleanCareerExtrasFinal(document);
    setTimeout(function(){cleanCareerExtrasFinal(document);},0);
  };

  document.addEventListener('click',function(e){
    if(e.target && e.target.closest && e.target.closest('#fm-tab-career,[for="fm-tab-career"],[data-profile-card-choice]')){
      setTimeout(function(){cleanCareerExtrasFinal(document);},0);
    }
  },true);

  try{cleanCareerExtrasFinal(document);}catch(_){}
})();
